INSERT INTO `ai_playerbot_texts` VALUES ('29', 'broadcast_looting_item_epic', 'OMG, look at what I just got %item_link!!!', '0', '0', '', 'OMG, regardez ce que je viens d’obtenir %item_link !!!', 'OMG, schaut euch an, was ich grad bekommen habe %item_link!!!', '卧槽快看我刚出的%item_link！！！', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('30', 'broadcast_looting_item_legendary', 'No @#$@% way! This can not be, I got %item_link, this is insane', '0', '0', '', 'Pas moyen! Ça ne peut pas être vrai, j’ai obtenu %item_link, c’est fou!', 'Nicht dein Ernst! Das kann nicht sein, ich hab %item_link bekommen, das ist irre!', '不可能！这不可能！我居然出了%item_link，太离谱了', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('31', 'broadcast_looting_item_artifact', 'No @#$@% way! This can not be, I got %item_link, this is insane', '0', '0', '', 'Pas possible! Ça ne peut pas être vrai, j’ai eu %item_link, c’est fou', 'Unfassbar! Das kann nicht sein, ich hab %item_link bekommen, das ist verrückt!', '不可能！这不可能！我居然出了%item_link，太离谱了', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('32', 'broadcast_looting_item_poor', 'Seriously? Another %item_link? My luck is broken.', '0', '0', '', 'Sérieusement? Encore un %item_link? La poisse me suit, c’est pas possible.', 'Ernsthaft? Noch ein %item_link? Ich habe kein Glück.', '认真的？又是%item_link？我运气被狗吃了', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('33', 'broadcast_looting_item_poor', 'This %item_link is not even worth the pixels it’s printed on.', '0', '0', '', 'Cet %item_link ne vaut même pas les pixels sur lesquels il est imprimé.', 'Dieser %item_link ist nicht mal die Pixel wert, auf denen er angezeigt wird.', '这%item_link连像素钱都不值', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('34', 'broadcast_looting_item_poor', 'I got %item_link... Ugh, here we go again.', '0', '0', '', 'J’ai de nouveau %item_link... Oh là là, c’est reparti.', 'Ich hab %item_link... Uff, schon wieder.', '又出%item_link...唉，经典复刻', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('35', 'broadcast_looting_item_poor', 'I don’t even know why I’m picking up %item_link, it’s useless.', '0', '0', '', 'Je me demande pourquoi je prends %item_link, c’est inutile.', 'Ich weiß nicht mal, warum ich %item_link aufhebe, ist eh nutzlos.', '我都不知道捡%item_link干嘛，纯占包', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('36', 'broadcast_looting_item_poor', 'Look at this shiny %item_link... too bad it’s garbage.', '0', '0', '', 'Regarde ce magnifique %item_link... dommage que ce soit de la camelote.', 'Schau dir dieses glänzende %item_link an... schade, dass es Müll ist.', '看这闪亮的%item_link...可惜是垃圾', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('37', 'broadcast_looting_item_poor', 'This %item_link isn’t even worth the paper it’s written on.', '0', '0', '', '%item_link ne vaut même pas le papier sur lequel il est écrit.', 'Dieser %item_link ist nicht mal das Papier wert, auf dem er steht.', '这%item_link连纸都不如', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('38', 'broadcast_looting_item_poor', 'I guess %item_link is better than nothing? Barely.', '0', '0', '', 'Je suppose que %item_link vaut mieux que rien ? À peine.', 'Ich schätze, %item_link ist besser als nichts? Gerade noch.', '%item_link总比没有强？勉强吧', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('39', 'broadcast_looting_item_poor', 'Not sure what to do with %item_link, maybe I’ll just sell it for 1 silver.', '0', '0', '', 'Je ne suis pas sûr de ce que faire avec %item_link, peut-être que je vais juste le vendre pour 1 pièce d’argent.', 'Keine Ahnung, was ich mit %item_link machen soll, vielleicht verkauf ich’s für 1 Silber.', '不知道%item_link有啥用，1银币挂拍卖行了', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('40', 'broadcast_looting_item_poor', 'Another %item_link... well, at least I’m getting something.', '0', '0', '', 'Encore un %item_link... eh bien, au moins je reçois quelque chose.', 'Noch ein %item_link... naja, immerhin bekomme ich was.', '又是%item_link...好吧，至少没空手', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('41', 'broadcast_looting_item_poor', 'I hope %item_link is actually worth something because it looks awful.', '0', '0', '', 'J’espère que %item_link vaut en fait quelque chose parce que ça a l’air affreux.', 'Hoffentlich ist %item_link wenigstens was wert, sieht nämlich furchtbar aus.', '希望%item_link值点钱，看着太磕碜了', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('42', 'broadcast_looting_item_poor', 'Is %item_link a joke? Someone’s laughing at me.', '0', '0', '', '%item_link c’est une blague ? Quelqu’un se moque de moi.', 'Ist %item_link ein Witz? Irgendwer lacht mich aus.', '%item_link是来搞笑的吗？有人在嘲讽我', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('43', 'broadcast_looting_item_poor', 'Why do I keep getting %item_link... did I anger RNG?', '0', '0', '', 'Pourquoi est-ce que je continue à obtenir %item_link... est-ce que j’ai fâché le RNG?', 'Warum krieg ich immer wieder %item_link... hab ich die RNG-Götter verärgert?', '为啥总出%item_link...我得罪RNG之神了？', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('44', 'broadcast_looting_item_poor', 'It’s like %item_link is following me around. I don’t want it!', '0', '0', '', 'C’est comme si %item_link me suivait partout. Je ne veux pas de ça !', 'Es ist, als würde %item_link mir nachlaufen. Ich will das nicht!', '%item_link像在跟踪我！我不想要啊！', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('45', 'broadcast_looting_item_poor', 'There’s %item_link, again. What a surprise.', '0', '0', '', 'Encore %item_link. Quelle surprise.', 'Schon wieder %item_link. Was für eine Überraschung.', '看啊，又是%item_link，毫无惊喜', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('46', 'broadcast_looting_item_poor', 'I guess %item_link is good for vendor trash?', '0', '0', '', 'I présume qu’ %item_link est bon pour vendre à un marchand ?', 'Ich schätze, %item_link taugt immerhin als Müll für den Händler?', '%item_link大概只能卖店吧？', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('47', 'broadcast_looting_item_poor', 'Noooo, not %item_link again! RNG, please!', '0', '0', '', 'Oh non, pas encore %item_link! RNG s’il te plaît!', 'Neeein, nicht schon wieder %item_link! RNG, bitte!', '不要啊！又是%item_link！RNG行行好！', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('48', 'broadcast_looting_item_poor', 'Well, at least %item_link isn’t completely useless, right?', '0', '0', '', 'Eh bien, au moins %item_link n’est pas complètement inutile, n’est-ce pas?', 'Naja, wenigstens ist %item_link nicht komplett nutzlos, oder?', '好吧，%item_link至少不全然没用对吧？', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('49', 'broadcast_looting_item_poor', 'Another %item_link? RNG, do you even care?', '0', '0', '', 'Encore %item_link ? La RNG est-ce que ça te dit quelque chose au moins?', 'Noch ein %item_link? RNG, interessiert dich das überhaupt?', '又是%item_link？RNG你认真的？', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('50', 'broadcast_looting_item_poor', 'Maybe %item_link will be worth something in 10 years.', '0', '0', '', 'Peut-être que %item_link vaudra quelque chose dans 10 ans.', 'Vielleicht ist %item_link in 10 Jahren mal was wert.', '也许十年后%item_link能值点钱', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('51', 'broadcast_looting_item_poor', 'I guess I’ll just admire how %item_link looks... and throw it away.', '0', '0', '', 'Je suppose que je vais juste admirer %item_link ... et le jeter.', 'Ich schätze, ich bewundere einfach, wie %item_link aussieht... und werfe es weg.', '我就欣赏下%item_link的外观...然后扔掉', '', '', '', '');
