INSERT INTO `ai_playerbot_texts` VALUES ('53', 'broadcast_looting_item_poor', 'Maybe %item_link will be useful... just kidding, it’s trash.', '0', '0', '', 'Peut-être que %item_link sera utile... non, je plaisante, c’est nul.', 'Vielleicht ist %item_link nützlich... nur Spaß, ist Müll.', '也许%item_link有用...开玩笑的，纯垃圾', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('54', 'broadcast_looting_item_poor', 'The universe has given me %item_link. Great.', '0', '0', '', 'L’univers m’a donné %item_link. Génial.', 'Das Universum hat mir %item_link geschenkt. Toll.', '宇宙赐予我%item_link，真棒', '', '', '', '');
