INSERT INTO `ai_playerbot_texts` VALUES ('59', 'broadcast_looting_item_poor', 'Another %item_link... RNG, we need to talk.', '0', '0', '', 'Encore un %item_link... RNG, on doit avoir une discussion.', 'Noch ein %item_link... RNG, wir müssen reden.', '又是%item_link...RNG，我们得谈谈', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('60', 'broadcast_looting_item_poor', 'I’ve looted so many %item_link, I could open a store with them.', '0', '0', '', 'J’ai récupéré tellement de %item_link, je pourrais ouvrir un magasin avec.', 'Ich hab so viele %item_link gelootet, ich könnte einen Laden eröffnen.', '我捡的%item_link都能开店了', '', '', '', '');
