INSERT INTO `ai_playerbot_texts` VALUES ('63', 'broadcast_looting_item_poor', 'Well, at least it’s %item_link... could be worse.', '0', '0', '', 'Eh bien, au moins c’est %item_link... ça pourrait être pire.', 'Naja, immerhin ist es %item_link... könnte schlimmer sein.', '好吧，至少是%item_link...还能更糟', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('64', 'broadcast_looting_item_poor', 'I’ll take %item_link over nothing.', '0', '0', '', 'Je préfère %item_link à rien du tout.', 'Lieber %item_link als gar nichts.', '有%item_link总比没有强', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('65', 'broadcast_looting_item_poor', 'Another %item_link. Not the worst.', '0', '0', '', 'Encore un %item_link. Pas le pire.', 'Noch ein %item_link. Geht schlimmer.', '又是%item_link，不算最差', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('66', 'broadcast_looting_item_poor', 'Hey, %item_link... it’s okay, I suppose.', '0', '0', '', 'Salut, %item_link... c’est correct, je suppose.', 'Hey, %item_link... naja, ist okay, denk ich.', '嘿，%item_link...还行吧', '', '', '', '');
