INSERT INTO `ai_playerbot_texts` VALUES ('68', 'broadcast_looting_item_normal', 'Could be worse... I just looted %item_link.', '0', '0', '', 'Ça aurait pu être pire... Je viens juste de mettre la main sur %item_link.', 'Könnte schlimmer sein... hab grad %item_link gelootet.', '可能更糟...我刚捡了%item_link', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('69', 'broadcast_looting_item_normal', 'I guess %item_link will come in handy for something.', '0', '0', '', 'Je suppose que %item_link va être utile pour quelque chose.', 'Ich schätze, %item_link wird irgendwann mal nützlich sein.', '%item_link应该能派上用场', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('70', 'broadcast_looting_item_normal', 'Another day, another %item_link. Can’t complain.', '0', '0', '', 'Encore une journée, encore un %item_link. Je ne vais pas me plaindre.', 'Neuer Tag, neues %item_link. Kann mich nicht beschweren.', '又是新一天，又是%item_link，没啥好抱怨', '', '', '', '');
