INSERT INTO `ai_playerbot_texts` VALUES ('331', 'broadcast_levelup_10x', 'Level %my_level, still a lot to go!', '0', '0', '', 'Niveau %my_level, il me reste encore beaucoup de chemin à parcourir !', 'Level %my_level, noch viel zu tun!', '%my_level级，还有很长的路！', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('332', 'broadcast_levelup_max_level', 'Finally hit level %my_level, I can do anything!', '0', '0', '', 'J’ai enfin atteint le niveau %my_level, je peux tout faire !', 'Endlich Level %my_level erreicht, jetzt geht alles!', '终于%my_level级，我能行！', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('333', 'broadcast_levelup_max_level', 'Max level %my_level, endgame here I come!', '0', '0', '', 'Niveau maximum %my_level atteint, je me rapproche de la fin du jeu !', 'Max-Level %my_level erreicht, Endgame ich komme!', '满级%my_level，终局内容我来了！', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('334', 'broadcast_levelup_max_level', 'Level %my_level! Ready for the endgame!', '0', '0', '', 'Niveau %my_level ! Prêt pour la phase finale !', 'Level %my_level! Bereit fürs Endgame!', '%my_level级！准备好终局内容了！', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('335', 'broadcast_levelup_max_level', 'Endgame unlocked at level %my_level, bring it on!', '0', '0', '', 'Fin du jeu débloquée au niveau %my_level, ça va déménager !', 'Endgame freigeschaltet auf Level %my_level, jetzt geht’s los!', '%my_level级解锁终局，放马过来！', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('336', 'broadcast_levelup_max_level', 'I’ve reached level %my_level, time to shine!', '0', '0', '', 'J’ai atteint le niveau %my_level, c’est le moment de briller!', 'Level %my_level erreicht, Zeit zu glänzen!', '我升到%my_level级，是时候发光了！', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('337', 'broadcast_levelup_max_level', 'Level %my_level, let’s do some endgame raiding!', '0', '0', '', 'Niveau %my_level, allons faire un raid de fin de jeu!', 'Level %my_level, Zeit für Endgame-Raids!', '%my_level级，搞点终局团本！', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('338', 'broadcast_levelup_max_level', 'At level %my_level, nothing can stop me now!', '0', '0', '', 'Au niveau %my_level, rien ne peut m’arrêter maintenant !', 'Auf Level %my_level kann mich nichts mehr aufhalten!', '%my_level级，现在没人能阻止我！', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('339', 'broadcast_levelup_max_level', 'Level %my_level, all systems go for high-level content!', '0', '0', '', 'Niveau %my_level, toutes les systèmes sont prêts pour du contenu de haut niveau !', 'Level %my_level, alle Systeme bereit für High-Level-Content!', '%my_level级，全力冲击高级内容！', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('340', 'broadcast_levelup_max_level', 'Yes! Level %my_level, %my_class ready for everything!', '0', '0', '', 'Oui! Niveau %my_level, %my_class prêt pour tout!', 'Ja! Level %my_level, %my_class bereit für alles!', '好耶！%my_level级%my_class准备就绪！', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('341', 'broadcast_levelup_max_level', 'Level %my_level, it’s time to take on the world!', '0', '0', '', 'Niveau %my_level, c’est le moment de conquérir le monde!', 'Level %my_level, jetzt wird die Welt erobert!', '%my_level级，是时候征服世界了！', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('342', 'broadcast_levelup_max_level', 'Reached level %my_level, let’s take on those elite bosses!', '0', '0', '', 'J’ai atteint le niveau %my_level, allons affronter ces boss d’élite!', 'Level %my_level erreicht, Zeit, die Elitebosse anzugehen!', '升到%my_level级，挑战精英BOSS去！', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('343', 'broadcast_levelup_max_level', 'Now I’m %my_level, the real adventure begins!', '0', '0', '', 'Maintenant que je suis %my_level, la vraie aventure commence!', 'Jetzt bin ich %my_level, das wahre Abenteuer beginnt!', '现在%my_level级，真正冒险开始！', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('344', 'broadcast_levelup_max_level', 'Level %my_level! Time for some serious action!', '0', '0', '', 'Niveau %my_level ! Il est temps d’entrer en action sérieusement !', 'Level %my_level! Jetzt wird’s ernst!', '%my_level级！该认真搞事了！', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('345', 'broadcast_levelup_max_level', 'Level %my_level and still growing stronger!', '0', '0', '', 'Niveau %my_level et je continue de devenir de plus en plus fort !', 'Level %my_level und werde immer stärker!', '%my_level级还在变强！', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('346', 'broadcast_levelup_max_level', 'Finally at level %my_level! Let’s show off what I can do!', '0', '0', '', 'Enfin, je suis au niveau %my_level ! Il est temps de montrer de quoi je suis capable !', 'Endlich Level %my_level! Zeit, zu zeigen, was ich draufhabe!', '终于%my_level级！秀操作的时候到了！', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('347', 'broadcast_levelup_max_level', 'Level %my_level is here! I’m ready for the big leagues!', '0', '0', '', 'Le niveau %my_level est arrivé! Je suis prêt pour les grands matchs!', 'Level %my_level erreicht! Bereit für die großen Herausforderungen!', '%my_level级来了！准备好打高级场了！', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('348', 'broadcast_levelup_max_level', 'Just hit %my_level, get ready for the real challenges!', '0', '0', '', 'Je viens d’atteindre mon niveau %my_level, je suis prêt pour affronter de vrais défis !', 'Gerade %my_level erreicht, jetzt kommen die echten Herausforderungen!', '刚升%my_level级，迎接真正挑战！', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('349', 'broadcast_levelup_max_level', 'Level %my_level complete, it’s time for the epic content!', '0', '0', '', 'Niveau %my_level complet, il est temps pour le contenu épique !', 'Level %my_level abgeschlossen, jetzt kommt das epische Zeug!', '%my_level级达成，该玩史诗内容了！', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('350', 'broadcast_levelup_max_level', 'Fresh out of %my_level! Ready for endgame dungeons!', '0', '0', '', 'Je viens enfin d’atteindre %my_level ! Prêt pour les donjons de fin de jeu !', 'Frisch Level %my_level erreicht! Bereit für Endgame-Dungeons!', '刚升%my_level级！准备好终局副本！', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('351', 'broadcast_levelup_max_level', 'Now that I’m level %my_level, nothing is beyond my reach!', '0', '0', '', 'Maintenant que je suis au niveau %my_level, rien ne peut m’arrêter !', 'Jetzt, wo ich Level %my_level bin, ist nichts mehr unmöglich!', '现在%my_level级，无所不能！', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('352', 'broadcast_levelup_max_level', 'It’s official! Level %my_level, time to dominate!', '0', '0', '', 'C’est officiel ! Niveau %my_level, c’est le moment de tout déchirer !', 'Es ist offiziell! Level %my_level, Zeit zu dominieren!', '官宣！%my_level级，统治时间到！', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('353', 'broadcast_levelup_max_level', 'Made it to level %my_level! Time to make my mark on the world!', '0', '0', '', 'J’ai atteint le niveau %my_level! Le moment de laisser ma trace dans le monde est enfin arrivé!', 'Level %my_level erreicht! Zeit, meinen Fußabdruck in der Welt zu hinterlassen!', '升到%my_level级！该在世界上留名了！', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('354', 'broadcast_levelup_max_level', 'Level %my_level unlocked! The real fun begins now!', '0', '0', '', 'Niveau %my_level débloqué! Maintenant, les choses sérieuses commencent!', 'Level %my_level freigeschaltet! Jetzt geht der Spaß erst richtig los!', '%my_level级解锁！真正乐趣现在开始！', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('355', 'broadcast_levelup_max_level', 'Level %my_level, and the world is my playground!', '0', '0', '', 'Niveau %my_level, et le monde est mon terrain de jeu!', 'Level %my_level, die Welt ist mein Spielplatz!', '%my_level级，世界是我的游乐场！', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('356', 'broadcast_levelup_max_level', 'Level %my_level, ready to show the world my power!', '0', '0', '', 'Niveau %my_level, prêt à montrer au monde ma puissance !', 'Level %my_level, bereit, der Welt meine Macht zu zeigen!', '%my_level级，准备向世界展示力量！', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('357', 'broadcast_levelup_max_level', 'Just hit %my_level, I’m going all in now!', '0', '0', '', 'Je viens d’atteindre %my_level, je me lance à fond maintenant !', 'Gerade %my_level erreicht, jetzt gebe ich alles!', '刚升%my_level级，现在全力出击！', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('358', 'broadcast_levelup_max_level', 'Level %my_level, I can finally take on everything!', '0', '0', '', 'Niveau %my_level, je peux enfin tout affronter !', 'Level %my_level, endlich kann ich alles in Angriff nehmen!', '%my_level级，终于能应付一切了！', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('359', 'broadcast_levelup_max_level', 'Level %my_level, I’m feeling unstoppable!', '0', '0', '', 'Niveau %my_level, je me sens imbattable!', 'Level %my_level, fühle mich unaufhaltsam!', '%my_level级，感觉无人能挡！', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('360', 'broadcast_levelup_max_level', 'Just reached level %my_level, can’t wait to dive into the endgame!', '0', '0', '', 'Je viens d’atteindre le niveau %my_level, j’ai hâte de me plonger dans le contenu de fin de jeu!', 'Gerade Level %my_level erreicht, kann es kaum erwarten, ins Endgame einzutauchen!', '刚升%my_level级，等不及进终局了！', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('361', 'broadcast_guild_promotion', 'Good job %other_name. You deserved this.', '0', '0', '', 'Bien joué %other_name. Tu l’as bien mérité.', 'Gut gemacht %other_name. Das hast du dir verdient.', '干得好%other_name，这是你应得的', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('362', 'broadcast_guild_demotion', 'That was awful %other_name. I hate to do this but...', '0', '0', '', 'Désolé %other_name, mais ça a été horrible. Je déteste devoir faire ça, mais...', 'Das war echt schlecht %other_name. Ich hasse es, das zu tun, aber...', '太烂了%other_name，我不想这样但...', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('363', 'broadcast_guild_promotion', 'Congrats %other_name, you’ve earned this promotion!', '0', '0', '', 'Félicitations %other_name, tu as mérité cette promotion !', 'Glückwunsch %other_name, du hast dir diese Beförderung verdient!', '恭喜%other_name，升职是你应得的！', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('364', 'broadcast_guild_promotion', 'Well deserved %other_name, welcome to the next level!', '0', '0', '', 'Bien mérité %other_name, bienvenue au niveau suivant !', 'Verdient %other_name, willkommen auf der nächsten Stufe!', '实至名归%other_name，欢迎晋级！', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('365', 'broadcast_guild_promotion', '%other_name is leveling up! Congratulations on the promotion!', '0', '0', '', '%other_name progresse dans sa carrière ! Félicitations pour la promotion !', '%other_name steigt auf! Glückwunsch zur Beförderung!', '%other_name升级了！恭喜晋升！', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('366', 'broadcast_guild_promotion', 'Promotion time! %other_name, you’ve earned this one!', '0', '0', '', 'Promotion time! %other_name, tu l’as bien mérité !', 'Beförderungszeit! %other_name, das hast du dir verdient!', '晋升时刻！%other_name，这是你应得的！', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('367', 'broadcast_guild_promotion', 'A new role for %other_name! Well done, keep it up!', '0', '0', '', 'Une nouvelle fonction pour %other_name ! Bravo, continue comme ça !', 'Eine neue Rolle für %other_name! Gut gemacht, weiter so!', '%other_name有新职位了！干得好，保持！', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('368', 'broadcast_guild_promotion', 'Huge congrats to %other_name, you’ve earned a well-deserved promotion!', '0', '0', '', '%other_name, félicitations pour ta super promotion, tu la mérites amplement!', 'Große Glückwünsche an %other_name, du hast dir diese Beförderung verdient!', '热烈祝贺%other_name，实至名归的晋升！', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('369', 'broadcast_guild_promotion', 'Let’s all give a round of applause to %other_name, for the promotion!', '0', '0', '', 'Donnons tous un grand round d’applaudissements à %other_name pour sa promotion!', 'Lasst uns %other_name für die Beförderung applaudieren!', '大家为%other_name的晋升鼓掌！', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('370', 'broadcast_guild_promotion', 'Cheers to %other_name on the promotion! Keep shining!', '0', '0', '', 'Salut à %other_name pour sa promotion! Continue de briller!', 'Prost auf %other_name zur Beförderung! Bleib am Ball!', '为%other_name的晋升干杯！继续发光！', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('371', 'broadcast_guild_promotion', 'Congrats %other_name, you’re moving up! Well done!', '0', '0', '', 'Félicitations %other_name, tu progresses dans ton parcours ! Bravo !', 'Glückwunsch %other_name, du steigst auf! Gut gemacht!', '恭喜%other_name，你升职了！干得好！', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('372', 'broadcast_guild_promotion', 'Another step up for %other_name! Congratulations!', '0', '0', '', 'Encore une promotion pour %other_name ! Félicitations !', 'Noch ein Aufstieg für %other_name! Glückwunsch!', '%other_name又进一步！恭喜！', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('373', 'broadcast_guild_demotion', 'Tough decision, but %other_name, you’ve been demoted. Time to step up!', '0', '0', '', 'Décision difficile, mais %other_name, tu as été rétrogradé. C’est le moment de te ressaisir!', 'Schwere Entscheidung, aber %other_name, du wurdest degradiert. Zeit, dich zu beweisen!', '艰难决定，%other_name你被降职了。该努力了！', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('374', 'broadcast_guild_demotion', 'Sorry %other_name, but it’s time for a demotion. Hope you come back stronger!', '0', '0', '', 'Désolé %other_name, mais c’est l’heure d’une rétrogradation. J’espère que tu reviendras plus fort !', 'Tut mir leid %other_name, aber es ist Zeit für eine Degradierung. Hoffe, du kommst stärker zurück!', '抱歉%other_name，该降职了。希望你更强归来！', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('375', 'broadcast_guild_demotion', 'Unfortunately, %other_name, it’s a demotion this time. You’ll get \'em next time!', '0', '0', '', '', 'Leider, %other_name, handelt es sich diesmal um eine Degradierung. Das nächste Mal kriegst du sie!', '不幸的是%other_name，这次降职。下次赢回来！', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('376', 'broadcast_guild_demotion', 'A hard decision, but %other_name, you’ve been demoted. Time to grind back up!', '0', '0', '', 'Une décision difficile, mais %other_name, tu as été rétrogradé. Il est temps de remonter la pente !', 'Schwere Entscheidung, aber %other_name, du wurdest degradiert. Zeit, dich wieder hochzuarbeiten!', '艰难决定，%other_name你被降职了。该重新肝了！', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('377', 'broadcast_guild_demotion', 'We hate to see it, but %other_name, it’s a demotion for now.', '0', '0', '', 'C’est toujours difficile à accepter, %other_name, mais pour le moment, c’est une rétrogradation.', 'Es ist nie schön, aber %other_name, du wurdest degradiert – vorerst.', '我们不愿看到，但%other_name暂时降职了', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('378', 'broadcast_guild_demotion', 'Sorry %other_name, your rank has been lowered. Let’s work harder together!', '0', '0', '', 'Désolé %other_name, ton rang a été abaissé. On va devoir redoubler d’efforts ensemble !', 'Tut mir leid %other_name, dein Rang wurde gesenkt. Lass uns gemeinsam härter arbeiten!', '抱歉%other_name，你降级了。一起努力吧！', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('379', 'broadcast_guild_demotion', 'A demotion for %other_name... Time to focus and rise back up!', '0', '0', '', 'Une rétrogradation pour %other_name... Il est temps de se concentrer et de remonter la pente!', 'Eine Degradierung für %other_name... Zeit, sich zu fokussieren und wieder aufzusteigen!', '%other_name降职了...该专注并东山再起！', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('380', 'broadcast_guild_demotion', 'Not what we wanted, but %other_name, you’ve been demoted. Learn and come back stronger!', '0', '0', '', 'Pas ce que nous voulions, mais %other_name, tu as été rétrogradé. Apprends et reviens plus fort !', 'Nicht das, was wir wollten, aber %other_name, du wurdest degradiert. Lern daraus und komm stärker zurück!', '非我们所愿，但%other_name降职了。学习并更强归来！', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('381', 'broadcast_guild_demotion', 'A tough moment for %other_name, but we know you can bounce back from this demotion!', '0', '0', '', 'Un moment difficile pour %other_name, mais on sait que tu peux rebondir après cette rétrogradation!', 'Ein harter Moment für %other_name, aber wir wissen, dass du dich von dieser Degradierung erholen kannst!', '%other_name艰难时刻，但我们知你能反弹！', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('382', 'broadcast_guild_demotion', 'Sorry %other_name, but a demotion has been applied. It’s time for improvement!', '0', '0', '', 'Désolé %other_name, mais une rétrogradation a été appliquée. Il est temps de s’améliorer !', 'Tut mir leid %other_name, aber du wurdest degradiert. Jetzt ist es Zeit, sich zu verbessern!', '抱歉%other_name，降职了。该改进了！', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('383', 'broadcast_guild_demotion', 'We didn’t want this for %other_name, but a demotion has occurred. Time to get better!', '0', '0', '', 'On n’a pas voulu cela pour %other_name, mais une rétrogradation a eu lieu. Il est temps de s’améliorer !', 'Das wollten wir nicht für %other_name, aber es ist zu einer Degradierung gekommen. Zeit, besser zu werden!', '我们不想这样，但%other_name降职了。该变强了！', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('384', 'broadcast_guild_recruitment', 'Looking for fresh blood! Join the guild, be part of something great!', '0', '0', '', 'À la recherche de sang neuf ! Rejoins la guilde, fais partie de quelque chose de grandiose !', 'Auf der Suche nach frischem Blut! Tritt der Gilde bei und sei Teil von etwas Großem!', '招新！加入公会，共创伟业！', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('385', 'broadcast_guild_recruitment', 'Recruiting members! If you’re ready to join us, the guild door is open!', '0', '0', '', 'Recrutement de membres ! Si tu es prêt à nous rejoindre, la porte de la guilde est ouverte!', 'Wir rekrutieren! Wenn du bereit bist, uns beizutreten, steht die Tür der Gilde offen!', '招人！准备好就加入，公会大门敞开！', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('386', 'broadcast_guild_recruitment', 'The guild is looking for skilled adventurers. Join us and thrive!', '0', '0', '', 'La guilde recherche des aventuriers compétents. Rejoins-nous et prospère!', 'Die Gilde sucht erfahrene Abenteurer. Tritt bei und wachse mit uns!', '公会招实力冒险者，加入一起成长！', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('387', 'broadcast_guild_recruitment', 'Want to join a great guild? We’re looking for new members! Come on in!', '0', '0', '', 'Envie de rejoindre une super guilde ? Nous cherchons de nouveaux membres ! Viens nous rejoindre !', 'Willst du einer großartigen Gilde beitreten? Wir suchen neue Mitglieder! Komm rein!', '想加好公会？我们在招新！快来！', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('388', 'broadcast_guild_recruitment', 'The guild is growing! Join us for exciting adventures and rewards!', '0', '0', '', 'La guilde grandit! Rejoignez-nous pour vivre des aventures palpitantes et obtenir des récompenses!', 'Die Gilde wächst! Schließ dich uns an für spannende Abenteuer und Belohnungen!', '公会壮大中！加入我们冒险领奖！', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('389', 'suggest_instance', 'Anyone wants %instance_name?', '0', '0', '', 'Qui veut %instance_name?', 'Wer will %instance_name?', '有人要打%instance_name吗？', '', '¿Alguien quiere ir a %instance_name?', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('390', 'suggest_instance', 'Any groups for %instance_name?', '0', '0', '', 'Des groupes pour %instance_name?', 'Gibt es Gruppen für %instance_name?', '有%instance_name的队吗？', '', '¿Algún grupo para %instance_name?', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('391', 'suggest_instance', 'Need help for %instance_name?', '0', '0', '', 'Besoin d’aide pour %instance_name ?', 'Braucht jemand Hilfe für %instance_name?', '需要帮忙打%instance_name吗？', '', '¿Alguien necesita ayuda con %instance_name?', '', '');
