INSERT INTO `ai_playerbot_texts` VALUES ('630', 'suggest_faction', 'I’ll never be %rep_level with %faction.', '0', '0', '', 'Je ne serai jamais %rep_level souhaité avec %faction.', 'Ich werde niemals %rep_level bei %faction erreichen.', '我永远到不了%faction的%rep_level', '', 'Nunca estaré %rep_level con %faction.', '', '');
