INSERT INTO `ai_playerbot_texts` VALUES ('633', 'suggest_faction', 'The more rep the better. Especially with %faction.', '0', '0', '', 'Plus il y a de réput, mieux c’est. Surtout avec %faction', 'Je mehr Ruf, desto besser. Besonders bei %faction.', '声望越多越好，尤其是%faction', '', 'Cuantas más repeticiones, mejor. Especialmente con %faction.', '', '');
