INSERT INTO `ai_playerbot_texts` VALUES ('637', 'suggest_faction', 'Wanna do %faction rep grind.', '0', '0', '', 'Je veux monter ma réputation avec la %faction.', 'Ich will Ruf farmen für %faction.', '想刷%faction声望', '', 'Quiero hacer %faction rep grind.', '', '');
