INSERT INTO `ai_playerbot_texts` VALUES ('639', 'suggest_faction', 'Farming for %faction rep.', '0', '0', '', 'Je fais du farm pour gagner de la réputation auprès de %faction.', 'Ich farme Ruf für %faction.', '在刷%faction声望', '', 'Farming for %faction rep.', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('640', 'suggest_faction', 'Wanna farm for %faction.', '0', '0', '', 'Envie de farmer pour %faction ?', 'Lust, %faction zu farmen?', '想刷%faction', '', 'Quiero farmear para %faction.', '', '');
