INSERT INTO `ai_playerbot_texts` VALUES ('644', 'suggest_faction', 'Who farms %faction?', '0', '0', '', 'Ah, qui farm %faction?', 'Wer farmt %faction?', '谁在刷%faction？', '', '¿Quién farmea %faction?', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('645', 'suggest_faction', 'Which is the best way to farm %faction?', '0', '0', '', 'Quelle est la meilleurs façon de farmer %faction ?', 'Was ist die beste Methode, um %faction zu farmen?', '刷%faction的最佳方式是啥？', '', '¿Cuál es la mejor manera de farmear %faction?', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('646', 'suggest_faction', 'I hate %faction rep grind.', '0', '0', '', 'Je déteste ce fichu grind de réputation pour %faction.', 'Ich hasse das Ruf-Farmen für %faction.', '我讨厌刷%faction声望', '', 'Odio %repetir de facción', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('647', 'suggest_faction', 'I am so tired of %faction.', '0', '0', '', 'Je suis tellement fatigué de cette %faction.', 'Ich bin so müde von %faction.', '我受够%faction了', '', 'Estoy tan cansado de %faction.', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('648', 'suggest_faction', 'Go for %faction?', '0', '0', '', 'Allez pour la %faction!', 'Gehen wir für %faction?', '去搞%faction吗？', '', '¿Quereis ir a por %faction?', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('649', 'suggest_faction', 'Seems everyone is %rep_level with %faction. Only me is late as usually.', '0', '0', '', 'Il semble que tout le monde soit au niveau %rep_level avec la faction %faction. Et bien sûr, je suis en retard comme d’habitude.', 'Sieht so aus, als wären alle %rep_level bei %faction. Nur ich bin wie immer zu spät.', '好像所有人都%faction%rep_level了，就我掉队', '', 'Parece que todo el mundo está %rep_level con %faction. Solo yo llego tarde como siempre.', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('650', 'suggest_faction', 'LFG for %faction rep grind?', '0', '0', '', 'Je recherche un groupe pour %faction rep grind !', 'Suche Gruppe für %faction Ruf-Farm!', '找队伍刷%faction声望？', '', 'Busco grupo para subir reputación con %faction', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('651', 'suggest_faction', 'Can anobody suggest a good spot for %faction rep grind?', '0', '0', '', 'Est-ce que quelqu’un peut me recommander un bon endroit pour gagner de la réputation avec %faction?', 'Kann jemand einen guten Spot für %faction Ruf-Farm empfehlen?', '有人能推荐刷%faction声望的好地方吗？', '', '¿Alguien puede sugerir un buen lugar farmear reputacion con %faction?', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('652', 'suggest_faction', 'Would %faction rep benefit me?', '0', '0', '', 'Est-ce que la réputation de %faction me sera bénéfique ?', 'Bringt mir der Ruf bei %faction etwas?', '%faction声望对我有用吗？', '', '¿Me beneficiaría subir reputación con %faction?', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('653', 'suggest_faction', 'Who would’ve thought that %faction rep will be useful after all...', '0', '0', '', 'Qui aurait pensé que cette réputation %faction serait finalement utile...', 'Wer hätte gedacht, dass Ruf bei %faction doch nützlich ist...', '谁能想到%faction声望居然有用...', '', 'Quién hubiera pensado que subir reputacion con %faction sería útil después de todo...', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('654', 'suggest_faction', 'I wanna be exalted with all factions, starting with %faction.', '0', '0', '', 'Je veux être honoré par toutes les factions, commençant par %faction.', 'Ich will bei allen Fraktionen ehrfürchtig sein, angefangen mit %faction.', '我想所有势力崇拜，从%faction开始', '', 'Quiero ser exaltado con todas las facciones, comenzando con %faction.', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('655', 'suggest_faction', 'Is there any point to improve my rep with %faction?', '0', '0', '', 'Est-ce que ça vaut la peine d’améliorer ma réputation avec la faction %faction ?', 'Lohnt es sich, meinen Ruf bei %faction zu verbessern?', '提升%faction声望有意义吗？', '', '¿Hay algún punto para mejorar mi reputación con %faction?', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('656', 'suggest_faction', 'What is better for %faction? Quests or mob grinding?', '0', '0', '', 'Pour %faction, il vaut mieux grind des mobs ou faire des quêtes ?', 'Was ist besser für %faction? Quests oder Mob-Farming?', '刷%faction声望任务好还是杀怪好？', '', '¿Qué es mejor para %faction? ¿Misiones o mafiosos?', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('657', 'suggest_faction', 'Will grind %faction rep for you. Just give me some gold.', '0', '0', '', 'Je vais augmenter la réputation de %faction pour toi. Il me suffit de me donner un peu d’or.', 'Ich farme %faction-Ruf für dich. Gib mir einfach etwas Gold.', '帮你刷%faction声望，给点金就行', '', 'Ganare reputacion con %faction por ti. Sólo dame un poco de oro.', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('658', 'suggest_faction', 'I think grinding rep with %faction would take forever.', '0', '0', '', 'Je pense que monter ma réputation avec %faction prendrait une éternité.', 'Ich glaube, Ruf farmen für %faction dauert ewig.', '我觉得刷%faction声望要刷到天荒地老', '', 'Creo que subir la reputación con %faction tomaría una eternidad.', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('659', 'suggest_faction', 'I am killing for %faction every day now but still far from %rep_level.', '0', '0', '', 'Je fais des missions pour la %faction tous les jours, mais je suis encore loin du niveau de réputation %rep_level.', 'Ich töte für %faction jeden Tag, aber bin noch weit entfernt von %rep_level.', '我每天为%faction杀怪，但离%rep_level还远', '', 'Estoy matando por %faction todos los días ahora, pero aún estoy lejos del %rep_level.', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('660', 'suggest_faction', 'At %my_level AH deposits will decrease, right?', '0', '0', '', 'À mon niveau %my_level, les dépôts AH vont diminuer, n’est-ce pas ?', 'Auf %my_level werden die Auktionshausgebühren sinken, oder?', '%my_level级拍卖行押金会降对吧？', '', 'Al %rep_level, los depósitos subastas disminuirán, ¿verdad?', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('661', 'suggest_faction', 'How many exalted reps do you have?', '0', '0', '', 'Combien de représentants exaltés avez-vous?', 'Wie viele ehrfürchtige Rufe hast du?', '你有几个崇拜声望了？', '', '¿Cuántas reputaciones exaltadas tienes?', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('662', 'suggest_faction', 'Who wants to be %my_level with %faction?', '0', '0', '', 'Qui veut être %my_level avec %faction?', 'Wer will %my_level bei %faction erreichen?', '谁想%faction声望到%my_level？', '', '¿Quién quiere estar en %rep_level con %faction?', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('663', 'suggest_faction', 'Damn. My guild did a good %faction grind yesterday without me.', '0', '0', '', 'Mince. Mon groupe a bien grindé la réputation %faction hier sans moi.', 'Verdammt. Meine Gilde hat gestern ordentlich %faction gefarmt ohne mich.', '靠，公会昨天刷%faction没带我', '', 'Maldición. Mi hermandad hizo un buen farmeo de %faction ayer sin mí.', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('664', 'suggest_faction', 'Nobody wants to help me because I am %rep_level with %faction.', '0', '0', '', 'Personne ne veut m’aider parce que je suis %rep_level avec %faction.', 'Niemand will mir helfen, weil ich %rep_level bei %faction bin.', '没人帮我，因为%faction声望%rep_level', '', 'Nadie quiere ayudarme porque estoy %rep_level con %faction.', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('665', 'suggest_faction', 'Please stay away from %faction.', '0', '0', '', 'S’il te plaît, garde tes distances avec %faction.', 'Bitte halte dich von %faction fern.', '请远离%faction', '', 'Por favor manténgase alejado de %faction.', '', '');
