INSERT INTO `ai_playerbot_texts` VALUES ('687', 'suggest_faction', 'Anyone farming %faction rep today?', '0', '0', '', 'Quelqu’un farme la réputation de la faction %faction aujourd’hui?', 'Farmt heute jemand %faction-Ruf?', '今天有人刷%faction声望吗？', '', '¿Alguien está farmeando reputación con %faction hoy?', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('688', 'suggest_faction', 'Need %faction rep help for %rep_level!', '0', '0', '', 'Besoin d’aide pour la réputation de %faction %rep_level %rep_level !', 'Brauche Hilfe für %faction-Ruf bis %rep_level!', '需要%faction声望帮助到%rep_level！', '', '¡Necesito ayuda con la reputación de %faction para %rep_level!', '', '');
