INSERT INTO `ai_playerbot_texts` VALUES ('818', 'suggest_something', 'Why is snow white but Ice is clear ? made of the same thing', '0', '0', '', 'Oh, la neige est blanche parce que ses cristaux reflètent la lumière du soleil, ce qui donne cette couleur. Tandis que la glace est claire car elle compacte les cristaux de glace, ce qui la rend transparente. C’est fou de penser que ce sont tous les deux faits de la même chose, n’est-ce pas ?', 'Schnee ist weiß, weil die Eiskristalle das Licht streuen, während Eis klar ist, weil es eine kompaktere Struktur hat.', '为啥雪是白的冰是透明的？明明同一种东西', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('819', 'suggest_something', 'why is whipped cream fluffy and regular not', '0', '0', '', 'Oh, whipped cream is all light and airy because we are beating some heavy cream until it traps air in. Regular cream just sits there all heavy and dense because it hasn’t been whipped yet. ', 'Schlagsahne ist luftig, weil beim Schlagen Luft eingeschlossen wird. Normale Sahne ist dicht und schwer, weil sie nicht aufgeschlagen wurde.', '为啥打发奶油是蓬松的而普通奶油不是', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('820', 'suggest_something', 'why do feet smell if they have no nose', '0', '0', '', 'Pourquoi les pieds sentent alors qu’ils n’ont pas de nez !?', 'Warum stinken Füße, wenn sie keine Nase haben?', '脚没鼻子为啥会臭', '', '', '', '');
