INSERT INTO `ai_playerbot_texts` VALUES ('882', 'suggest_something_toxic', 'so wait, do i need armor to be a true hero or is it optional', '0', '0', '', 'Alors, attends, est-ce que j’ai besoin d’une armure pour être un vrai héros ou est-ce facultatif ?', 'Warte mal, brauche ich eine Rüstung, um ein echter Held zu sein, oder ist das optional?', '等等，当英雄必须穿护甲吗？还是可选的？', '', '', '', '');
