INSERT INTO `ai_playerbot_texts` VALUES ('886', 'suggest_something_toxic', 'why doesn’t my horse fly? can’t it just go up', '0', '0', '', 'Pourquoi mon cheval ne vol pas ? Pourquoi il ne peut juste pas aller vers le ciel ?', 'Warum fliegt mein Pferd nicht? Kann es nicht einfach hochgehen?', '我的马为啥不会飞？它不能往上走吗', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('887', 'suggest_something_toxic', 'Is there an option to turn off the graphics so it looks like my old calculator', '0', '0', '', 'Il n’y a pas une option pour désactiver les graphismes calculette ? Le jeu est vraiment moche.', 'Gibt es eine Option, die Grafik auszuschalten, damit es aussieht wie mein alter Taschenrechner?', '有关闭画面让游戏像老计算器的选项吗', '', '', '', '');
