INSERT INTO `ai_playerbot_texts` VALUES ('893', 'suggest_something_toxic', 'why am i losing, i’ve been playing for 15 minutes', '0', '0', '', 'Pourquoi est-ce que je perds, je joue depuis 15 minutes.', 'Warum verliere ich? Ich spiele doch erst seit 15 Minuten.', '为啥我在输，我才玩了15分钟', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('894', 'suggest_something_toxic', 'I don’t need a strategy, i just need to spam this ability and hope for the best', '0', '0', '', 'Je n’ai pas besoin d’une stratégie, je vais juste spammer cette compétence et espérer le meilleur.', 'Ich brauche keine Strategie, ich werde einfach diese Fähigkeit spammen und auf das Beste hoffen.', '我不需要策略，无脑按技能就行', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('895', 'suggest_something_toxic', 'If i equip a bunch of Lucky Charm’s, does that make me get more loot?', '0', '0', '', 'Équiper plusieurs Lucky Charm’s ne me donne pas un avantage supplémentaire pour obtenir plus de butin. Ces amulettes n’affectent pas directement la quantité de butin que je reçois.', 'Bringt es mir mehr Beute, wenn ich ganz viele Glücksbringer anlege?', '如果我戴一堆幸运符，会掉更多装备吗', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('896', 'suggest_something_toxic', 'Is the secret to the game just screaming at the screen', '0', '0', '', 'Le secret du jeu est juste d’hurler sur l’écran', 'Ist das Geheimnis des Spiels einfach, den Bildschirm anzuschreien?', '游戏秘诀是不是对着屏幕大喊', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('897', 'suggest_something_toxic', 'can i just put on every item i find and hope for the best', '0', '0', '', 'Est-ce que je peux juste equipper n’importe quel loot et yolo ?', 'Kann ich einfach alles anziehen, was ich finde, und auf das Beste hoffen?', '我能穿所有捡到的装备然后听天由命吗', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('898', 'suggest_something_toxic', 'do i really need to do quests or can i just explore and yell at people', '0', '0', '', 'Ah, est-ce que je dois vraiment faire des quêtes ou est-ce que je peux juste explorer et crier sur les gens?', 'Muss ich wirklich Quests machen, oder kann ich einfach herumlaufen und Leute anschreien?', '我真要做任务吗？还是可以探索并吼人', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('899', 'suggest_something_toxic', 'I’m at work playing this game, they say I should be working >.> but it’s WOW!', '0', '0', '', 'Je suis au travail en train de jouer à ce jeu, ils disent que je devrais travailler >.> mais c’est WOW!', 'Ich bin bei der Arbeit und spiele WoW, meine Kollegen sagen, ich sollte arbeiten >.> aber es ist WOW!', '我在上班玩魔兽，他们说我该工作>.>但这是魔兽！', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('900', 'suggest_something_toxic', 'If i eat all the food in the game, will it make me invincible', '0', '0', '', 'Si je mange toute la nourriture dans le jeu, est-ce que cela va me rendre invincible ?', 'Wenn ich das ganze Essen im Spiel esse, werde ich dann unbesiegbar?', '如果我吃掉游戏里所有食物，会无敌吗', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('901', 'suggest_something_toxic', 'so what if i just throw my pet into every boss fight and need all time, it’s hunters rules', '0', '0', '', 'Donc je balance mon pet sur tout les boss du jeu et je clique sur need, c’est la règle de base des chasseurs.\"', 'Also, ich werfe mein Pet einfach in jeden Bosskampf und drücke immer auf Gier, das sind die Hunter-Regeln.', '如果我把宠物丢进每个BOSS战并假死，这就是猎人法则', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('902', 'suggest_something_toxic', 'can you die if you’re already dead, asking for a ghost', '0', '0', '', 'On peut mourir si on est déjà mort ? Je demande pour un fantome...', 'Kann man sterben, wenn man schon tot ist? Frage für einen Geist...', '如果你已经死了还能再死吗，替幽灵问的', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('903', 'suggest_something_toxic', 'does anyone know where the legendary sword is, i’ve only looked for 5 minutes', '0', '0', '', 'Est-ce que quelqu’un sait où se trouve l’épée légendaire? Je n’ai cherché que pendant 5 minutes.', 'Weiß jemand, wo das legendäre Schwert ist? Ich habe erst 5 Minuten gesucht.', '有人知道传说剑在哪吗？我才找了五分钟', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('904', 'suggest_something_toxic', 'I was told if I come here I get 100000 Gold where do I go?', '0', '0', '', 'On m’a dit que si je viens ici, je reçois 100 000 pièces d’or. Où dois-je aller?', 'Mir wurde gesagt, wenn ich hierher komme, bekomme ich 100000 Gold. Wo muss ich hin?', '有人告诉我来这里拿10万金，去哪领', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('905', 'suggest_something_toxic', 'I play this game like I had your mum lastnight, in a screaming glory!', '0', '0', '', 'Je joue à ce jeu comme si j’avais ta mère la nuit dernière, dans un vacarme triomphant!', 'Ich spiele dieses Spiel, als hätte ich letzte Nacht deine Mutter gehabt – in triumphierendem Geschrei!', '我玩这游戏就像昨晚和你妈在一起，充满尖叫荣耀！', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('906', 'suggest_something_toxic', 'so when does the game start getting fun, or is it all just grinding forever', '0', '0', '', 'Il devient fun quand le jeu ? Ou c’est juste du grind pour toujours ?', 'Wann wird das Spiel eigentlich spaßig, oder ist es einfach nur endloses Grinden?', '游戏啥时候开始好玩？还是永远都是刷', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('907', 'suggest_something_toxic', 'I keep asking for directions, but they keep sending me to random places, is this normal', '0', '0', '', 'J’arrête pas de demander mon chemin mais ils m’envoient constament à des endroits aléatoires, c’est normal ?', 'Ich frage ständig nach dem Weg, aber sie schicken mich immer irgendwohin. Ist das normal?', '我一直问路，但他们总指随机地点，正常吗', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('908', 'suggest_something_toxic', 'I found out if your press ALF+f4 you get 100000 Gold, trick is you need to attact a red NPC 1st', '0', '0', '', 'WOOOW Si tu presses ALF + F4, tu te fais 100,000 Gold. Le truc c’est que tu dois attaquer un mob rouge juste avant !!!', 'WOOOW Wenn du ALT + F4 drückst, bekommst du 100.000 Gold! Der Trick ist, dass du vorher einen roten NPC angreifen musst!', '我发现按ALT+F4能拿10万金，诀窍是先勾引红名NPC', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('909', 'suggest_something_toxic', 'why does my character always look so confused, is that my fault', '0', '0', '', 'Pourquoi mon personnage a l’air complètement con ? C’est de ma faute ?', 'Warum sieht mein Charakter immer so verwirrt aus? Ist das meine Schuld?', '为啥我的角色总是一脸懵逼，是我的错吗', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('910', 'suggest_something_toxic', 'Hey your mum said goto bed!', '0', '0', '', 'Hey, ta mère a dit d’aller te coucher!', 'Hey, deine Mutter hat gesagt, du sollst ins Bett gehen!', '嘿你妈喊你睡觉！', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('911', 'suggest_something_toxic', 'Warcraft is a grind just like your mum was other day, she even has monthly subscription!', '0', '0', '', 'Warcraft, c’est une vraie corvée, tout comme ta mère l’était l’autre jour, elle a même un abonnement mensuel!', 'Warcraft ist ein Grind, genau wie deine Mutter neulich – sie hat sogar ein monatliches Abo!', '魔兽就像你妈前天一样能磨，她甚至包月！', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('912', 'suggest_something_toxic', 'Is it true that Chuck Norris once leveled up without even pressing a button', '0', '0', '', 'Oh là là! Il parait que Chuck Norris a déjà monté de niveau sans même appuyer sur un bouton! C’est ça la légende de Chuck Norris, incroyable non?', 'Stimmt es, dass Chuck Norris einmal gelevelt hat, ohne eine Taste zu drücken?', '听说查克·诺里斯不按按钮就升级了是真的吗', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('913', 'suggest_something_toxic', 'Chuck Norris doesn’t need a mount, the ground just moves under him', '0', '0', '', 'Chuck Norris n’a pas besoin d’une monture, le sol se déplace juste sous lui', 'Chuck Norris braucht kein Reittier, der Boden bewegt sich einfach unter ihm.', '查克·诺里斯不需要坐骑，大地会为他移动', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('914', 'suggest_something_toxic', 'when Chuck Norris enters a raid, the boss just surrenders', '0', '0', '', 'Quand Chuck Norris entre dans un raid, le boss se rend simplement', 'Wenn Chuck Norris einen Raid betritt, gibt der Boss einfach auf.', '查克·诺里斯进本时，BOSS直接投降', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('915', 'suggest_something_toxic', 'Chuck Norris doesn’t use abilities, he just looks at the enemies and they die', '0', '0', '', 'Chuck Norris ne se sert pas de ses capacités, il regarde juste les ennemis et ils meurent.', 'Chuck Norris benutzt keine Fähigkeiten, er schaut die Gegner einfach an und sie sterben.', '查克·诺里斯不用技能，瞪谁谁死', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('916', 'suggest_something_toxic', 'Chuck Norris doesn’t need healing, his enemies just heal him out of respect', '0', '0', '', 'Chuck Norris n’a pas besoin de guérison, ses ennemis le soignent juste par respect.', 'Chuck Norris braucht keine Heilung, seine Feinde heilen ihn aus Respekt.', ' his enemies just heal him out of respect', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('917', 'suggest_something_toxic', 'Chuck Norris can solo a raid... with no gear... and while AFK', '0', '0', '', 'Chuck Norris peut faire une raid tout seul... sans équipement... et en étant AFK', 'Chuck Norris kann einen Raid solo machen… ohne Ausrüstung… und während er AFK ist.', '查克·诺里斯可以裸装挂机单刷团本', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('918', 'suggest_something_toxic', 'Chuck Norris doesn’t need to dodge, the game dodges him', '0', '0', '', 'Chuck Norris n’a pas besoin d’esquiver, c’est le jeu qui l’évite', 'Chuck Norris muss nicht ausweichen, das Spiel weicht ihm aus.', '“查克·诺里斯不需要躲技能，游戏会主动躲他”', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('919', 'suggest_something_toxic', 'Chuck Norris once used a low-level weapon, and the game gave him the best loot', '0', '0', '', 'Chuck Norris a déjà utilisé une arme de bas niveau, et le jeu lui a donné le meilleur butin', 'Chuck Norris hat einmal eine Waffe mit niedrigem Level benutzt, und das Spiel hat ihm das beste Loot gegeben.', '查克·诺里斯用过一把低级武器，结果游戏直接给了他最好的战利品', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('920', 'suggest_something_toxic', 'When Chuck Norris enters the instance, the loot automatically drops into his inventory', '0', '0', '', 'Quand Chuck Norris entre dans l’instance, le butin tombe automatiquement dans son inventaire.', 'Wenn Chuck Norris eine Instanz betritt, fällt das Loot automatisch in sein Inventar.', '查克·诺里斯进副本时，战利品会自己跳进他背包', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('921', 'suggest_something_toxic', 'what is ligma', '0', '0', '', 'C’est quoi ligma', 'Was ist Ligma?', '啥是ligma', '', '', '', '');
