INSERT INTO `ai_playerbot_texts` VALUES ('931', 'suggest_something_toxic', 'cool boner, bro', '0', '0', '', 'Belle bite bro', 'Coole Latte, Bro.', '兄弟，硬得可以啊', '', '', '', '');
