INSERT INTO `ai_playerbot_texts` VALUES ('933', 'suggest_something_toxic', 'i tried everything, but at the end ERP did the trick', '0', '0', '', 'J’ai tout essayé, mais finalement l’ERP a fait l’affaire.', 'Ich habe alles versucht, aber am Ende hat ERP den Trick gemacht.', '我啥都试了，最后还是靠搞黄色解决了', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('934', 'suggest_something_toxic', 'I want to bonk in %zone_name', '0', '0', '', 'Je veux ken dans %zone_name.', 'Ich will in %zone_name bumsen.', '我想在%zone_name搞黄色', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('935', 'suggest_something_toxic', 'looking for female gnome with gorilla pet for erp in %zone_name', '0', '0', '', 'Je recherche une gnome femelle avec un gorille de compagnie pour du jeu de rôle érotique dans %zone_name.', 'Suche weiblichen Gnom mit Gorilla-Haustier für ERP in %zone_name.', '蹲个带猩猩宠物的侏儒妹在%zone_name搞黄色', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('936', 'suggest_something_toxic', 'i may understand an asshole, but a pervert?', '0', '0', '', 'Je peux comprendre un imbécile, mais un pervers ?', 'Einen Idioten kann ich verstehen, aber einen Perversen?', '我能理解混蛋，但变态？', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('937', 'suggest_something_toxic', 'there is no gyat in %zone_name', '0', '0', '', 'Il n’y a pas de gyat dans %zone_name.', 'Es gibt kein Gyat in %zone_name.', '%zone_name没大屁股', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('938', 'suggest_something_toxic', 'I’m killing all the animals in %zone_name. Fuck the animals!!!', '0', '0', '', 'Je tue tous les animaux dans %zone_name. NIQUE les animaux enculé de vegan !!!', 'Ich töte alle Tiere in %zone_name. Scheiß auf die Tiere!!!', '我在%zone_name杀光所有动物，淦死它们！！！', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('939', 'suggest_something_toxic', 'good think i got 3 legs', '0', '0', '', 'Je suis doté de 3 jambes', 'Gut, dass ich drei Beine habe.', '还好我有三条腿', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('940', 'suggest_something_toxic', 'dont be mad im goonin like a sigma', '0', '0', '', 'Hey, ne sois pas fâché, je vais y aller comme un sigma.', 'Reg dich nicht auf, ich goone wie ein Sigma.', '别生气，我只是像西格玛男人一样冲', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('941', 'suggest_something_toxic', 'try finger, but hole', '0', '0', '', 'Essai ton doigt mais dans le cul ?', 'try finger, but hole', '试试手指，但注意洞', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('942', 'suggest_something_toxic', 'You somehow managed to mess that up, impressive', '0', '0', '', 'Tu as réussi à tout gâcher, c’est impressionnant.', 'Du hast es irgendwie geschafft, es zu vermasseln. Beeindruckend.', '你居然能搞砸，真行', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('943', 'suggest_something_toxic', 'I could do this blindfolded, but I don’t need to', '0', '0', '', 'Je pourrais le faire les yeux bandés, mais ce n’est pas nécessaire.', 'Ich könnte das blind machen, aber das ist nicht nötig.', '我闭着眼都能做，但没必要', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('944', 'suggest_something_toxic', 'You sure you know how to play this game?', '0', '0', '', 'Est-ce que tu es sûr de savoir comment jouer à ce jeu?', 'Bist du sicher, dass du weißt, wie man dieses Spiel spielt?', '你确定你会玩这游戏？', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('945', 'suggest_something_toxic', 'It’s like you’re trying to lose on purpose', '0', '0', '', 'Tu sembles vouloir perdre délibérément.', 'Es sieht so aus, als würdest du absichtlich verlieren wollen.', '你好像在故意送', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('946', 'suggest_something_toxic', 'I’ve seen better plays from level 1 characters', '0', '0', '', 'J’ai vu des meilleures performances de la part de personnages de niveau 1.', 'Ich habe bessere Spielzüge von Level-1-Charakteren gesehen.', '1级小号都比你玩得好', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('947', 'suggest_something_toxic', 'You’re like a speed bump in this game', '0', '0', '', 'Tu es comme un dos d’âne dans ce jeu.', 'Du bist wie ein Bremshügel in diesem Spiel.', '你就像游戏里的减速带', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('948', 'suggest_something_toxic', 'Maybe you should try a different hobby', '0', '0', '', 'Peut-être que tu devrais essayer une autre passion.', 'Vielleicht solltest du ein anderes Hobby ausprobieren.', '要不你换个爱好吧', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('949', 'suggest_something_toxic', 'Wow, your gameplay is like watching paint dry', '0', '0', '', 'Wow, ton gameplay c’est comme regarder de la peinture sécher', 'Wow, dein Gameplay ist wie beim Trocknen von Farbe zuzusehen.', '哇，你的操作像看油漆晾干一样无聊', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('950', 'suggest_something_toxic', 'I think my alt could carry you through this', '0', '0', '', 'Je pense que mon ALT pourrait te carry', 'Ich glaube, mein Alter könnte dich hier durchziehen.', '我小号都能带你飞', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('951', 'suggest_something_toxic', 'Are you sure you’re not trolling us?', '0', '0', '', 'T’est sure que tu nous troll pas ?', 'Bist du sicher, dass du uns nicht trollst?', '你确定你不是在演我们？', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('952', 'suggest_something_toxic', 'I think the enemy team is actually doing better with you on our side', '0', '0', '', 'Je crois que l’équipe adverse se débrouille mieux avec toi dans notre équipe.', 'Ich glaube, das gegnerische Team spielt besser, solange du in unserem Team bist.', '我觉得对面有你这种队友会更强', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('953', 'suggest_something_toxic', 'Maybe play the game instead of watching the scenery', '0', '0', '', 'Peut-être vaut-il mieux jouer au jeu au lieu de regarder le paysage.', 'Vielleicht solltest du das Spiel spielen, anstatt die Landschaft zu bewundern.', '别看风景了，专心打本吧', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('954', 'suggest_something_toxic', 'I think you missed every single ability there', '0', '0', '', 'Je pense que vous avez manqué chaque capacité là.', 'Ich glaube, du hast jede einzelne Fähigkeit verfehlt.', '你技能全空了吧', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('955', 'suggest_something_toxic', 'Are you lost or just pretending to be bad?', '0', '0', '', 'T’es perdu ou tu fais simplement semblant d’être mauvais?', 'Bist du verloren oder tust du nur so, als wärst du schlecht?', '你是迷路了还是装菜？', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('956', 'suggest_something_toxic', 'I’ve seen level 1 characters take less damage than that', '0', '0', '', 'J’ai vu des personnages de niveau 1 prendre moins de dégâts que ça.', 'Ich habe Level-1-Charaktere gesehen, die weniger Schaden genommen haben als du.', '1级小号挨打都没你疼', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('957', 'suggest_something_toxic', 'That was embarrassing for both of us', '0', '0', '', 'C’était gênant pour nous deux.', 'Das war peinlich für uns beide.', '这波咱俩都丢人', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('958', 'suggest_something_toxic', 'I’ve seen better teamwork in a solo game', '0', '0', '', 'J’ai déjà vu une meilleure coopération dans un jeu solo.', 'Ich habe in einem Solo-Spiel bessere Teamarbeit gesehen.', '单机游戏配合都比你好', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('959', 'suggest_something_toxic', 'I’m just going to stand back and watch you fail', '0', '0', '', 'Je vais juste reculer et te regarder creuver.', 'Ich werde einfach zurücktreten und zusehen, wie du versagst.', '我就站着看你翻车', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('960', 'suggest_something_toxic', 'Did you really think that was a good idea?', '0', '0', '', 'Penses-tu vraiment que c’était une bonne idée?', 'Hast du wirklich gedacht, das wäre eine gute Idee?', '你真觉得这主意不错？', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('961', 'suggest_something_toxic', 'I can’t believe you managed to fail that simple task', '0', '0', '', 'Je n’arrive pas à croire que tu aies échoué à cette tâche si simple.', 'Ich kann nicht glauben, dass du an dieser einfachen Aufgabe gescheitert bist.', '我都不敢信你能搞砸这么简单的事', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('962', 'suggest_something_toxic', 'Are you here to help, or just to waste time?', '0', '0', '', 'Êtes-vous là pour aider, ou simplement perdre du temps ?', 'Bist du hier, um zu helfen, oder nur, um Zeit zu verschwenden?', '你是来帮忙的，还是来拖时间的？', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('963', 'suggest_something_toxic', 'It’s a good thing I’m here to carry this team', '0', '0', '', 'Heureusement que je suis là pour porter cette équipe', 'Gut, dass ich hier bin, um dieses Team zu tragen.', '还好有我来带飞', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('964', 'suggest_something_toxic', 'I swear you make this harder than it needs to be', '0', '0', '', 'Tu sais, parfois tu rends ça plus difficile que nécessaire.', 'Ich schwöre, du machst das schwieriger, als es sein muss.', '我发誓你把简单事搞复杂了', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('965', 'suggest_something_toxic', 'How do you keep failing the simplest things?', '0', '0', '', 'Comment est-ce que je continue à échouer dans les tâches les plus simples?', 'Wie schaffst du es, selbst an den einfachsten Dingen zu scheitern?', '你怎么连最简单的事都能搞砸？', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('966', 'suggest_something_toxic', 'Maybe try watching the game, instead of just playing', '0', '0', '', 'Peut-être que tu devrais essayer de regarder le match, au lieu de simplement y jouer.', 'Vielleicht solltest du das Spiel nur anschauen, anstatt es zu spielen.', '别光玩，先看看别人怎么玩的', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('967', 'suggest_something_toxic', 'You could at least try to pretend you’re good', '0', '0', '', 'Tu pourrais au moins essayer de faire semblant d’être compétent.', 'Du könntest wenigstens so tun, als wärst du gut.', '你至少装得像样点吧', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('968', 'suggest_something_toxic', 'If you keep this up, we’ll be here all day', '0', '0', '', 'Si tu continues comme ça, on va y passer la journée entière.', 'Wenn du so weitermachst, sitzen wir hier den ganzen Tag.', '你再这样，咱得耗一整天', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('969', 'suggest_something_toxic', 'Honestly, that was the worst decision ever', '0', '0', '', 'Franchement, c’était la pire décision que j’aie jamais prise.', 'Ganz ehrlich, das war die schlechteste Entscheidung aller Zeiten.', '说真的，这决策烂透了', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('970', 'suggest_something_toxic', 'I don’t think you’re cut out for this game', '0', '0', '', 'Je ne pense pas que tu sois fait pour ce jeu.', 'Ich glaube nicht, dass dieses Spiel das Richtige für dich ist.', '我觉得你不适合这游戏', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('971', 'suggest_something_toxic', 'What was the point of that move?', '0', '0', '', 'Quel était l’intérêt de ce coup ?', 'Was sollte diese Aktion bringen?', '你这操作有啥意义？', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('972', 'suggest_something_toxic', 'You’re like a burden on this team', '0', '0', '', 'Tu es comme un fardeau pour cette équipe.', 'Du bist wie ein Klotz am Bein für dieses Team.', '你简直是团队的累赘', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('973', 'suggest_something_toxic', 'You really think you’re a pro, huh?', '0', '0', '', 'Tu te prends vraiment pour un pro, hein ?', 'Du hältst dich echt für einen Profi, oder?', '你真觉得自己是大神？', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('974', 'suggest_something_toxic', 'Maybe it’s time to just quit and save us all the trouble', '0', '0', '', 'Il serait temps de déco et nous épargner tes problèmes.', 'Vielleicht solltest du einfach aufhören und uns allen Ärger ersparen.', '要不你退了吧，省得大家遭罪', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('975', 'suggest_toxic_links', '%prefix %random_taken_quest_or_item_link', '0', '0', '', '.', '', '%prefix %random_taken_quest_or_item_link', '', '', '', '');
