INSERT INTO `ai_playerbot_texts` VALUES ('979', 'thunderfury_spam', '%thunderfury_link%thunderfury_link%thunderfury_link', '0', '0', '', '', '', '%thunderfury_link%thunderfury_link%thunderfury_link', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('980', 'thunderfury_spam', 'I think I just heard %thunderfury_link', '0', '0', '', 'J’ai entendu %thunderfury_link', 'Ich glaube, ich habe gerade %thunderfury_link gehört.', '我好像听到%thunderfury_link', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('981', 'thunderfury_spam', 'I think I heard %thunderfury_link', '0', '0', '', 'Je viens juste d’entendre %thunderfury_link', 'Ich glaube, ich habe %thunderfury_link gehört.', '我好像听到%thunderfury_link', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('982', 'thunderfury_spam', 'I definitely heard %thunderfury_link', '0', '0', '', 'Je suis sûr d’avoir entendu parler de %thunderfury_link.', 'Ich bin mir sicher, dass ich %thunderfury_link gehört habe.', '我绝对听到%thunderfury_link了', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('983', 'thunderfury_spam', 'I dunno but I’m pretty sure I heard %thunderfury_link', '0', '0', '', 'Je ne sais pas, mais je suis presque certain d’avoir entendu %thunderfury_link.', 'Keine Ahnung, aber ich bin mir ziemlich sicher, dass ich %thunderfury_link gehört habe.', '不确定，但我八成听到%thunderfury_link了', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('984', 'thunderfury_spam', 'Did you just say %thunderfury_link', '0', '0', '', 'Qui vient de parler de %thunderfury_link?', 'Hast du gerade %thunderfury_link gesagt?', '你刚说%thunderfury_link了？', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('985', 'thunderfury_spam', 'did someone say %thunderfury_link', '0', '0', '', 'Oh, vous avez mentionné %thunderfury_link ?', 'Hat jemand gerade %thunderfury_link erwähnt?', '有人提到%thunderfury_link？', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('986', 'thunderfury_spam', 'Did someone say %thunderfury_link ?', '0', '0', '', 'Qui a mentionné %thunderfury_link ?', 'Hat jemand %thunderfury_link gesagt?', '有人提到%thunderfury_link吗？', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('987', 'thunderfury_spam', 'Someone said %thunderfury_link', '0', '0', '', 'Quelqu’un a mentionné %thunderfury_link.', 'Jemand hat %thunderfury_link erwähnt.', '有人说%thunderfury_link', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('988', 'thunderfury_spam', '%thunderfury_link is coming out of the closet', '0', '0', '', '%thunderfury_link sort du placard', '%thunderfury_link kommt aus dem Schrank heraus.', '%thunderfury_link出柜了', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('989', 'thunderfury_spam', 'could swear it was a %thunderfury_link, might have been %thunderfury_link tho', '0', '0', '', 'Je pourrais jurer que c’était un %thunderfury_link, mais ça aurait aussi pu être %thunderfury_link en fait.', 'Ich könnte schwören, es war ein %thunderfury_link, aber es könnte auch %thunderfury_link gewesen sein.', '我发誓是%thunderfury_link，不过也可能是%thunderfury_link', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('990', 'thunderfury_spam', 'Why use %thunderfury_link when %thunderfury_link is clearly way more OP', '0', '0', '', 'Pourquoi utiliser %thunderfury_link quand %thunderfury_link est clairement beaucoup plus puissant.', 'Warum %thunderfury_link benutzen, wenn %thunderfury_link eindeutig viel stärker ist?', '有更强的%thunderfury_link为啥要用%thunderfury_link', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('991', 'thunderfury_spam', 'Did I just hear %thunderfury_link?', '0', '0', '', 'Ai-je juste entendu %thunderfury_link?', 'Habe ich gerade %thunderfury_link gehört?', '我是不是听到%thunderfury_link了？', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('992', 'thunderfury_spam', 'No way... is that a %thunderfury_link I hear?', '0', '0', '', 'Pas possible... Est-ce que j’entends %thunderfury_link ?', 'Unmöglich... Habe ich da etwa %thunderfury_link gehört?', '不会吧……我听到%thunderfury_link了？', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('993', 'thunderfury_spam', '%thunderfury_link? Sounds like something only legends wield!', '0', '0', '', '%thunderfury_link? Ça a l’air d’être quelque chose que seuls les légendes manient!', '%thunderfury_link? Klingt nach etwas, das nur Legenden führen!', '%thunderfury_link？这玩意只有传说中的人才有吧！', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('994', 'thunderfury_spam', 'I can feel the power of %thunderfury_link in the air!', '0', '0', '', 'Je peux sentir la puissance de %thunderfury_link dans l’air !', 'Ich kann die Macht von %thunderfury_link in der Luft spüren!', '我感受到空气中%thunderfury_link的力量！', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('995', 'thunderfury_spam', '%thunderfury_link is the *real* MVP', '0', '0', '', '%thunderfury_link est le *vrai* MVP.', '%thunderfury_link ist der *wahre* MVP.', '%thunderfury_link才是真大腿', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('996', 'thunderfury_spam', 'Can someone get me a %thunderfury_link? Asking for a friend... maybe even two!', '0', '0', '', 'Est-ce que quelqu’un peut me trouver un %thunderfury_link ? Je demande pour un ami... peut-être même deux !', 'Kann mir jemand ein %thunderfury_link besorgen? Frage für einen Freund... oder zwei!', '谁能给我搞把%thunderfury_link？帮朋友问的……可能两把！', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('997', 'thunderfury_spam', 'Hey, did %thunderfury_link just *smite* something? I swear I felt the ground shake.', '0', '0', '', 'Hey, est-ce que %thunderfury_link vient de *foudroyer* quelque chose ? Je te jure que j’ai senti la terre trembler.', 'Hey, hat %thunderfury_link gerade etwas *erschlagen*? Ich schwöre, ich habe den Boden beben gespürt.', '嘿，%thunderfury_link是不是刚劈了啥？我发誓地面震了', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('998', 'thunderfury_spam', '%thunderfury_link on the battlefield... It’s like an instant flex.', '0', '0', '', '%thunderfury_link sur le champ de bataille... C’est comme montrer sa puissance instantanément.', '%thunderfury_link auf dem Schlachtfeld... Das ist purer Flex.', '战场上掏出%thunderfury_link……直接装到了', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('999', 'thunderfury_spam', 'I *think* I heard %thunderfury_link... Or was that just a myth?', '0', '0', '', '*Je crois* avoir entendu %thunderfury_link... Ou peut-être que c’était juste un mythe?', '*Ich glaube*, ich habe %thunderfury_link gehört... Oder war das nur ein Mythos?', '我好像听到%thunderfury_link了……还是说这只是传说？', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1000', 'thunderfury_spam', 'Wait, did I just see someone wielding %thunderfury_link?!', '0', '0', '', 'Attends, est-ce que je viens de voir quelqu’un manier %thunderfury_link ?!', 'Warte mal, habe ich gerade jemanden gesehen, der %thunderfury_link führt?!', '等等，我刚看到有人拿着%thunderfury_link？！', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1001', 'thunderfury_spam', 'The power of %thunderfury_link is *undeniable*', '0', '0', '', 'Le pouvoir de %thunderfury_link est *indéniable*', 'Die Macht von %thunderfury_link ist *unbestreitbar*', '%thunderfury_link的力量*无可否认*', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1002', 'thunderfury_spam', 'I’m 99% sure that was %thunderfury_link. 1% might have been a random NPC, tho.', '0', '0', '', 'Je suis à 99% certain que c’était %thunderfury_link. Le 1% restant aurait pu être un PNJ aléatoire, cependant.', 'Ich bin zu 99% sicher, dass das %thunderfury_link war. Die restlichen 1% könnten ein zufälliger NPC gewesen sein.', '我有99%确定那是%thunderfury_link。剩下1%可能是个路人NPC吧。', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1003', 'thunderfury_spam', '%thunderfury_link in action! Who needs an army when you’ve got that kind of power?', '0', '0', '', '%thunderfury_link en action ! Qui a besoin d’une armée lorsqu’on a ce genre de puissance ?', '%thunderfury_link in Aktion! Wer braucht eine Armee, wenn man so eine Macht hat?', '%thunderfury_link发威了！有这种力量还要什么军队？', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1004', 'thunderfury_spam', 'I heard %thunderfury_link is what really brings all the boys to the yard.', '0', '0', '', 'J’ai entendu dire que %thunderfury_link, c’est ce qui attire vraiment tous les garçons dans la cour.', 'Ich habe gehört, dass %thunderfury_link wirklich alle Jungs in den Hof lockt.', '我听说%thunderfury_link才是真·吸睛神器。', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1005', 'thunderfury_spam', 'Why even use %thunderfury_link when %thunderfury_link is clearly the superior option?', '0', '0', '', 'Pourquoi même utiliser %thunderfury_link quand %thunderfury_link est clairement l’option supérieure ?', 'Warum überhaupt %thunderfury_link benutzen, wenn %thunderfury_link klar die bessere Option ist?', '明明%thunderfury_link更强，为啥还要用%thunderfury_link？', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1006', 'thunderfury_spam', 'Is it me or does %thunderfury_link have a “smack talk” passive effect?', '0', '0', '', 'Est-ce moi ou est-ce que %thunderfury_link a un effet passif de provocation ?', 'Bin ich der Einzige, oder hat %thunderfury_link eine passive “Trash Talk”-Fähigkeit?', '%thunderfury_link是不是自带\"嘲讽\"被动啊？', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1007', 'thunderfury_spam', 'I thought I heard %thunderfury_link, but it was just the sound of sheer awesome.', '0', '0', '', 'J’ai cru entendre %thunderfury_link, mais en fait c’était juste le son de la pure puissance.', 'Ich dachte, ich hätte %thunderfury_link gehört, aber es war nur der Klang reiner Epikness.', '我以为是%thunderfury_link，结果只是单纯的牛逼声。', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1008', 'thunderfury_spam', 'Oh, %thunderfury_link... Where *have* you been all my life?', '0', '0', '', 'Oh, %thunderfury_link ... Où as-tu été tout ce temps, ma belle épée ?', 'Oh, %thunderfury_link... Wo *warst* du mein ganzes Leben lang?', '哦，%thunderfury_link…你*这些年*都藏哪儿了？', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1009', 'thunderfury_spam', 'Did someone say %thunderfury_link? I think I need to go pick mine up.', '0', '0', '', '%thunderfury_link? Oh là là, j’entends toujours parler de cet incroyable objet! Je crois bien qu’il est temps pour moi d’aller le chercher.', 'Hat jemand %thunderfury_link gesagt? Ich glaube, ich muss meine jetzt auch abholen.', '刚才有人说%thunderfury_link？我该去拿我的了。', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1010', 'thunderfury_spam', 'That was definitely the sound of %thunderfury_link! I can feel the epicness.', '0', '0', '', 'C’était certainement le son de %thunderfury_link ! Je peux sentir toute son épopée.', 'Das war definitiv der Klang von %thunderfury_link! Ich kann die Epikness spüren.', '这绝对是%thunderfury_link的声响！史诗感拉满。', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1011', 'thunderfury_spam', 'Is it just me, or does %thunderfury_link have a tendency to make everyone else *look* weak?', '0', '0', '', 'C’est moi ou bien %thunderfury_link a tendance à faire paraître les autres faibles?', 'Bin ich der Einzige, oder lässt %thunderfury_link alle anderen *schwach* aussehen?', '是我错觉吗？%thunderfury_link总让别人*显得*很菜。', '', '', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1012', 'thunderfury_spam', 'You know what they say... the louder the %thunderfury_link, the bigger the bragging rights!', '0', '0', '', 'Tu sais ce qu’on dit... plus le %thunderfury_link rugit, plus grand sont les droits de vantardise!', 'Du weißt, was man sagt... je lauter das %thunderfury_link, desto größer die Prahlrechte!', '俗话说…%thunderfury_link越响，吹逼权越大！', '', '', '', '');
