INSERT INTO `ai_playerbot_texts` VALUES ('1027', 'suggest_sell', 'I have %item_formatted_link and need more.', '0', '0', '', 'J’ai %item_formatted_link et j’en ai besoin de plus.', 'Ich habe %item_formatted_link und brauche mehr.', '我有%item_formatted_link，但还想要更多。', '', 'Tengo %item_formatted_link y necesito más. ¿Alguien me vende alguno?', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1028', 'suggest_sell', 'Have %item_formatted_link. Who wants to buy for %cost_gold?', '0', '0', '', 'J’ai %item_formatted_link. Qui veut acheter pour %cost_gold?', 'Ich habe %item_formatted_link. Wer will es für %cost_gold kaufen?', '有%item_formatted_link，谁要买？%cost_gold金。', '', 'Tengo %item_formatted_link. ¿Quién quiere comprarlo por %cost_gold?', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1029', 'suggest_sell', 'Anyone WTB %item_formatted_link for %cost_gold?', '0', '0', '', 'Quelqu’un veut acheter %item_formatted_link pour %cost_gold?', 'Will jemand %item_formatted_link für %cost_gold kaufen?', '有人收%item_formatted_link吗？%cost_gold金。', '', '¿Alguien compra %item_formatted_link por %cost_gold?', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1030', 'suggest_sell', 'What about %item_formatted_link? For %cost_gold.', '0', '0', '', 'Qu’en est-il de %item_formatted_link ? Pour %cost_gold.', 'Was ist mit %item_formatted_link? Für %cost_gold.', '%item_formatted_link怎么样？%cost_gold金就卖。', '', '¿Qué pasa con %item_formatted_link? Por el oro.', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1031', 'suggest_sell', 'Who said I am a bastard? %item_formatted_link for %cost_gold is a good price.', '0', '0', '', 'Qui a dit que je suis un bâtard ? %item_formatted_link pour %cost_gold, c’est un bon prix.', 'Wer hat gesagt, dass ich ein Gauner bin? %item_formatted_link für %cost_gold ist ein guter Preis.', '谁说我是奸商？%item_formatted_link卖%cost_gold金很良心了！', '', '¿Quién ha dicho que soy un rata? %item_formatted_link por %cost_gold es una ganga.', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1032', 'suggest_sell', 'I am selling %item_formatted_link? Just %cost_gold.', '0', '0', '', 'Je vends %item_formatted_link à seulement %cost_gold.', 'Ich verkaufe %item_formatted_link? Nur %cost_gold.', '卖%item_formatted_link，只要%cost_gold金。', '', '¿Vendo %item_formatted_link? Solo %cost_gold.', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1033', 'suggest_sell', 'LFG for farming. You can still buy %item_formatted_link I have for %cost_gold.', '0', '0', '', 'Je cherche des gens pour farmer. Tu peux toujours acheter %item_formatted_link que j’ai pour %cost_gold.', 'LFG für Farmruns. Du kannst immer noch %item_formatted_link für %cost_gold kaufen.', '组队刷本中，顺便卖%item_formatted_link，%cost_gold金。', '', 'LFG para farmear. Todavía puedes comprar %item_formatted_link que tengo por %cost_gold.', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1034', 'suggest_sell', 'Sold almost everything today. Still have %item_formatted_link for %cost_gold.', '0', '0', '', 'J’ai presque tout vendu aujourd’hui. Il me reste seulement %item_formatted_link pour %cost_gold.', 'Habe heute fast alles verkauft. Habe nur noch %item_formatted_link für %cost_gold.', '今天清仓大甩卖，还剩%item_formatted_link，%cost_gold金。', '', 'Se vendió casi todo hoy. Todavía tengo %item_formatted_link por %cost_gold.', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1035', 'suggest_sell', 'What use for trade chat? Of course to sell %item_formatted_link for %cost_gold.', '0', '0', '', 'Pourquoi utiliser le chat de commerce ? Eh bien, évidemment pour vendre mon %item_formatted_link au prix de %cost_gold.', 'Wofür gibt es den Handelschat? Natürlich um %item_formatted_link für %cost_gold zu verkaufen.', '交易频道当然是用来卖%item_formatted_link的，%cost_gold金。', '', '¿De qué sirve el chat comercial? Por supuesto, para vender %item_formatted_link por %cost_gold.', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1036', 'suggest_sell', 'Can anyone beat the price of %cost_gold for %item_formatted_link?', '0', '0', '', 'Est-ce que quelqu’un peut battre le prix de %cost_gold pour %item_formatted_link ?', 'Kann jemand den Preis von %cost_gold für %item_formatted_link unterbieten?', '%item_formatted_link卖%cost_gold金，有更低的吗？', '', '¿Alguien puede superar el precio de %cost_gold por %item_formatted_link?', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1037', 'suggest_sell', 'Wanna stop trade chat? Just buy %item_formatted_link? For %cost_gold!', '0', '0', '', 'Tu veux arrêter le chat commercial ? Il suffit d’acheter %item_formatted_link ! Pour seulement %cost_gold !', 'Willst du den Handelschat stoppen? Kauf einfach %item_formatted_link für %cost_gold!', '想让我闭嘴？%cost_gold金买走%item_formatted_link就行！', '', '¿Quieres detener el chat comercial? ¿Solo compra %item_formatted_link? ¡Por el oro!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1038', 'suggest_sell', 'Everybody spams in trade chat. Me too - %cost_gold for %item_formatted_link!', '0', '0', '', 'Tout le monde spamme dans le chat commercial. Moi aussi - %cost_gold pour %item_formatted_link !', 'Jeder spammt im Handelschat. Ich auch – %cost_gold für %item_formatted_link!', '都在刷屏？我也来——%item_formatted_link卖%cost_gold金！', '', 'Todo el mundo envía spam en el chat y yo también! ¡%item_formatted_link por %cost_gold!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1039', 'suggest_sell', 'Is %item_formatted_link any use? Just selling it for %cost_gold.', '0', '0', '', 'Est-ce que %item_formatted_link est utile ? Je le vends juste pour %cost_gold.', 'Ist %item_formatted_link überhaupt nützlich? Verkaufe es nur für %cost_gold.', '%item_formatted_link有用吗？反正%cost_gold金卖了。', '', '¿Es %item_formatted_link útil? Solo lo vendo por %cost_gold.', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1040', 'suggest_sell', 'I have %item_formatted_link ready to sell you for %cost_gold.', '0', '0', '', 'J’ai %item_formatted_link prêt à te vendre pour %cost_gold.', 'Ich habe %item_formatted_link zum Verkauf für %cost_gold.', '%item_formatted_link现货，%cost_gold金拿走。', '', 'Tengo %item_formatted_link listo a la venta por %cost_gold.', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1041', 'suggest_sell', 'Did nothing yesterday but have got %item_formatted_link. Selling it for %cost_gold.', '0', '0', '', 'Je n’ai rien fait hier mais j’ai %item_formatted_link Je le vends pour %cost_gold', 'Habe gestern nichts gemacht, aber %item_formatted_link bekommen. Verkaufe es für %cost_gold.', '昨天啥也没干，但捡到%item_formatted_link，%cost_gold金出。', '', 'No hice nada ayer pero consegu’i %item_formatted_link. Lo vendo por %cost_gold.', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1042', 'suggest_sell', 'Farmed yesterday and got %item_formatted_link. Anyone wtb for %cost_gold?', '0', '0', '', 'J’ai farmé hier et j’ai obtenu %item_formatted_link. Quelqu’un est intéressé pour %cost_gold ?', 'Gestern gefarmt und %item_formatted_link bekommen. Will jemand es für %cost_gold kaufen?', '昨天刷本出了%item_formatted_link，%cost_gold金有人要吗？', '', 'Ayer farmee y conseguí mucho %item_formatted_link. ¿Alguien lo quiere comprar por %cost_gold?', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1043', 'suggest_sell', 'Bought %item_formatted_link yesterday. Anyone needs it for %cost_gold?', '0', '0', '', 'J’ai acheté %item_formatted_link hier. Est-ce que quelqu’un en a besoin pour %cost_gold?', 'Habe gestern %item_formatted_link gekauft. Braucht es jemand für %cost_gold?', '昨天买了%item_formatted_link，%cost_gold金转手。', '', 'Ayer compré %item_formatted_link. ¿Alguien lo quiere por %cost_gold?', '', '');
