INSERT INTO `ai_playerbot_texts` VALUES ('1045', 'suggest_sell', 'I sill have %item_formatted_link. WTB for %cost_gold?', '0', '0', '', 'J’ai toujours %item_formatted_link. Je cherche à l’acheter pour %cost_gold.', 'Ich habe immer noch %item_formatted_link. Will jemand es für %cost_gold kaufen?', '我还有%item_formatted_link，%cost_gold金收吗？', '', 'Todavía tengo %item_formatted_link. ¿Alguien lo compra por %cost_gold?', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1046', 'suggest_sell', 'I used to have more than %item_formatted_link. Now needs to sell it for %cost_gold.', '0', '0', '', 'J’avais plus de %item_formatted_link avant. Maintenant, je dois le vendre pour %cost_gold.', 'Früher hatte ich mehr als %item_formatted_link. Jetzt muss ich es für %cost_gold verkaufen.', '以前囤过%item_formatted_link，现在%cost_gold金清仓。', '', 'Solía tener más de %item_formatted_link. Ahora necesito venderlo por %cost_gold.', '', '');
