INSERT INTO `ai_playerbot_texts` VALUES ('1048', 'suggest_sell', 'What use for your gold? To buy my %item_formatted_link for %cost_gold.', '0', '0', '', 'Que vais-je faire de ton or ? Acheter mon %item_formatted_link pour %cost_gold.', 'Wofür dein Gold? Um mein %item_formatted_link für %cost_gold zu kaufen.', '你的金币能干嘛？当然是%cost_gold金买我的%item_formatted_link。', '', '¿De qué sirve tu oro? Para comprar mi %item_formatted_link por %cost_gold.', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1049', 'suggest_sell', 'Please spare some gold for me. You can buy %item_formatted_link for %cost_gold.', '0', '0', '', 'S’il vous plaît, épargnez-moi de l’or. Vous pouvez acheter %item_formatted_link pour %cost_gold', 'Bitte gib mir etwas Gold. Du kannst %item_formatted_link für %cost_gold kaufen.', '行行好，%cost_gold金买走我的%item_formatted_link吧。', '', 'Por favor, dame algo de oro. Puedes comprar %item_formatted_link por %cost_gold.', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1050', 'suggest_sell', 'Is %cost_gold is a good price for %item_formatted_link?', '0', '0', '', 'Est-ce que %cost_gold, c’est un bon prix pour %item_formatted_link?', 'Ist %cost_gold ein guter Preis für %item_formatted_link?', '%cost_gold金买%item_formatted_link算好价吗？', '', '¿%cost_gold es un buen precio para %item_formatted_link?', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1051', 'suggest_sell', 'Just bought yesterday %item_formatted_links, but do not need it anymore. Anyone wants for %cost_gold?', '0', '0', '', 'Hier, j’ai acheté %item_formatted_links, mais je n’en ai plus besoin. Est-ce que quelqu’un le veut pour %cost_gold?', 'Gestern habe ich %item_formatted_links gekauft, brauche es aber nicht mehr. Will es jemand für %cost_gold?', '昨天刚买的%item_formatted_links，现在用不上了。有人要吗？%cost_gold金。', '', 'Ayer compré %item_formatted_link, pero ya no los necesito. ¿Alguien lo quiere por %cost_gold?', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1052', 'suggest_sell', 'I am going to post %item_formatted_link on the AH but you can buy it now cheaper just for %cost_gold.', '0', '0', '', 'Je vais mettre en vente %item_formatted_link sur l’HV, mais tu peux l’acheter maintenant à un prix réduit, pour seulement %cost_gold.', 'Ich werde %item_formatted_link ins AH stellen, aber du kannst es jetzt günstiger für %cost_gold kaufen.', '我准备把%item_formatted_link挂拍卖行，但现在%cost_gold金直接卖你更便宜。', '', 'Voy a poner %item_formatted_link en la casa de subastas pero puedes comprarlo ahora más barato solo por %cost_gold.', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1053', 'suggest_sell', 'Why the #!@ have I bought %item_formatted_link? Anyone needs it for %cost_gold?', '0', '0', '', 'Pourquoi diable ai-je acheté %item_formatted_link? Est-ce que quelqu’un en a besoin pour %cost_gold?', 'Warum zum Teufel habe ich %item_formatted_link gekauft? Braucht es jemand für %cost_gold?', '我脑子抽了买%item_formatted_link？%cost_gold金有人收吗？', '', '¿Por qué #!@ he comprado %item_formatted_link? ¿Alguien lo necesita por %cost_gold?', '', '');
