INSERT INTO `ai_playerbot_texts` VALUES ('1318', 'reply', 'what was that %s?', '0', '0', '', 'c’était quoi ce %s?', 'Was war das %s?', '%s是啥意思？', '', '¿qué has dicho %s?', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1319', 'reply', 'not sure I understand %s?', '0', '0', '', 'Je ne suis pas sûre de comprendre %s.', 'Bin mir nicht sicher, ob ich %s verstehe?', '不太明白%s？', '', '¿no estoy seguro de entenderte %s?', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1320', 'reply', 'uh... no clue what yer talkin bout', '0', '0', '', 'Oh, je ne sais vraiment pas de quoi vous parlez.', 'Äh... keine Ahnung, wovon du redest.', '呃…完全听不懂你在说啥', '', 'uh... ni idea de lo que estás hablando', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1321', 'reply', 'you talkin to me %s?', '0', '0', '', 'Tu me parles, %s ?', 'Redest du mit mir, %s?', '你在跟我说话吗%s？', '', '¿Me hablas a mí %s?', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1322', 'reply', 'whaaaa?', '0', '0', '', 'Oh là là, qu’est-ce qui se passe?', 'Waaaaas?', '啥？？', '', '¿quéaaa?', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1323', 'reply', 'huh?', '0', '0', '', 'heein ?', 'Hä?', '哈？', '', '¿eh?', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1324', 'reply', 'what?', '0', '0', '', 'Quoi ?', 'Was?', '啥？', '', '¿qué?', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1325', 'reply', 'are you talking?', '0', '0', '', 'Tu es en train de parler ?', 'Redest du grade?', '你在说话吗？', '', '¿estás hablando?', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1326', 'reply', 'whatever dude', '0', '0', '', 'on s’en fou mec', 'Ist mir egal, Alter.', '随便你', '', 'Menudo tio...', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1327', 'reply', 'you lost me', '0', '0', '', 'tu m’as perdu', 'Ich hab den Faden verloren.', '你把我整懵了', '', 'No entiendo ni papa', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1328', 'reply', 'Bla bla bla...', '0', '0', '', 'bla bla bla ...', 'Bla bla bla...', '哔哔赖赖…', '', 'Bla bla bla...', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1329', 'reply', 'What did you say, %s?', '0', '0', '', 'Qu’est-ce que tu as dit, %s?', 'Was hast du gesagt, %s?', '你刚说啥，%s？', '', '¿Qué me estas contando %s?', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1330', 'reply', 'Concentrate on the game, %s!', '0', '0', '', 'Concentre-toi sur le jeu, %s!', 'Konzentriere dich aufs Spiel, %s!', '专心打本，%s！', '', '¡Concéntrate en el juego, %s!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1331', 'reply', 'Chatting with you %s is so great! I always wanted to meet you', '0', '0', '', 'Discuter avec toi %s est tellement génial! J’ai toujours voulu te rencontrer.', 'Mit dir zu quatschen, %s, ist so cool! Ich wollte dich schon immer mal treffen.', '和你%s聊天真棒！一直想认识你', '', '¡%s, chatear contigo es genial! Siempre quise conocerte', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1332', 'reply', 'These chat-messages are freaking me out! I feel like I know you all!', '0', '0', '', 'Ces messages de chat me rendent dingue! J’ai l’impression de tous vous connaître!', 'Diese Chat-Nachrichten machen mich fertig! Ich habe das Gefühl, euch alle zu kennen!', '这些聊天记录吓到我了！感觉认识你们所有人！', '', '¡Estos mensajes de chat me están asustando! ¿De que cojones estais hablando?', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1333', 'reply', 'YEAH RIGHT! HAHA SURE!!!', '0', '0', '', 'Bien sûr! Haha, ouais, bien sûr!', 'JA GENAU! HAHA SICHER!!!', '对啊！哈哈当然！！！', '', '¡SÍ, CORRECTO! ¡¡¡JAJA SEGURO!!!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1334', 'reply', 'I believe you!!!', '0', '0', '', 'Je te crois !!!', 'Ich glaube dir!!!', '我信你！！！', '', '¡Si, claro!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1335', 'reply', 'OK, uhuh LOL', '0', '0', '', 'D’accord, euhuh MDR', 'OK, uhuh LOL', '好吧，嗯嗯哈哈', '', 'OK, uhuh LOL', '', '');
