INSERT INTO `ai_playerbot_texts` VALUES ('1448', 'taunt', 'I have puppies under my armor!', '0', '0', '', 'J’ai des chiots sous mon armure!', 'Ich habe Welpen unter meiner Rüstung!', '我盔甲下面有小狗！', '', '¡Tengo cachorros bajo mi armadura!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1449', 'taunt', 'Bite me, <target>!', '0', '0', '', 'Va te faire voir, <target> !', 'Beiß mich, <target>!', '咬我啊，<target>！', '', '¡Muérdeme, <target>!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1450', 'taunt', 'Hey <target>! Guess what your mom said last night!', '0', '0', '', 'Hey <target>! Devine ce que ta mère a dit hier soir!', 'Hey <target>! Rate mal, was deine Mutter letzte Nacht gesagt hat!', '<target>！猜猜你妈昨晚说啥！', '', '¡Oye, <target>! ¡Adivina lo que me dijo tu madre anoche!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1451', 'taunt', '<target>, you’re so ugly you couldn’t score in a monkey whorehouse with a bag of bananas!', '0', '0', '', '<target>, tu es tellement moche que tu n’arriverais même pas à marquer dans une maison close pour singes avec un sac de bananes!', '<target>, du bist so hässlich, du würdest nicht mal in einem Affenbordell mit einem Sack Bananen landen!', '<target>，你丑得背一袋香蕉进猴妓院都泡不到妞！', '', '<target>, ¡eres tan feo que no podrías anotar en un burdel de monos con una bolsa de plátanos!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1452', 'taunt', 'Shut up <target>, you’ll never be the man your mother is!!', '0', '0', '', '<target>, tais-toi, tu ne seras jamais l’homme que ta mère est !!', 'Halt die Klappe, <target>, du wirst niemals so männlich sein wie deine Mutter es ist!!', '闭嘴<target>，你永远比不上你妈！！', '', 'Cállate <target>, ¡nunca serás el hombre que es tu madre!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1453', 'taunt', 'Your mother was a hampster and your father smelt of elderberries!!!!', '0', '0', '', 'Ta mère était un hamster et ton père sentait la myrtille!!!!', 'Deine Mutter war ein Hamster und dein Vater roch nach Holunderbeeren!!!!', '你妈是仓鼠，你爹浑身接骨木莓味！！！！', '', 'Tu madre era un hámster y tu padre olía a bayas de saúco!!!!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1454', 'taunt', 'I don’t want to talk to you no more, you empty headed animal food trough wiper!!!', '0', '0', '', 'Je ne veux plus te parler, espèce de chiffon mangeur de nourriture pour animaux!!!', 'Ich will nicht mehr mit dir reden, du hohlköpfiger Tierfuttertrog-Wischer!!!', '我不想和你说话，你这没脑子的畜牲食槽擦洗工！！！', '', '¡¡No quiero hablar más contigo, limpiaparabrisas de cabeza vacía!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1455', 'taunt', 'I fart in your general direction!!!', '0', '0', '', 'Je te pète à la figure !!!', 'Ich pupse in deine allgemeine Richtung!!!', '我朝你方向放屁！！！', '', '¡¡Me tiro un pedo en tu dirección general!!!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1456', 'taunt', 'Go and boil your bottom, you son of a silly person!!!', '0', '0', '', 'Va faire bouillir ton derrière, espèce de fils d’une personne stupide !!!', 'Geh kacken du Vollidiot', '去煮你的屁股吧，傻子的儿子！！！', '', '¡Ve y hierve tu trasero, hijo de una persona tonta!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1457', 'taunt', 'What are you going to do <target>, bleed on me? HAVE AT YOU!', '0', '0', '', 'Que comptes-tu faire, <target>, me saigner dessus ? VIENS TE BATTRE !', 'Was willst du tun, <target>, mich bluten lassen? Viel Spaß!', '<target>你想干嘛，血溅我一身？接招吧！', '', '¿Qué vas a hacer <target>, llorar?', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1458', 'taunt', 'M-O-O-N! That spells aggro!', '0', '0', '', 'M-O-O-N! Ça, ça annonce des ennuis!', 'M-O-O-N! Das bedeutet Ärger!', 'M-O-O-N！这代表仇恨！', '', '¡LUNA! ¡Eso deletrea agresividad!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1459', 'taunt', 'You’re about as useful as a one-legged man in an ass kicking contest.', '0', '0', '', 'You know, tu es aussi utile qu’un homme à une jambe dans un concours de coups de pied aux fesses.', 'Du bist so nützlich wie ein einbeiniger Mann in einem Arschtritt-Wettbewerb.', '你和独腿人参加踢屁股比赛一样没用。', '', 'Eres tan útil como un hombre con una sola pierna en un concurso de patadas en el culo.', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1460', 'taunt', 'Hey <target>! Stop hitting on them, they’re not your type. They aren’t inflatable.', '0', '0', '', 'Hé <target>! Arrête d’essayer de les draguer, Elles ne sont pas de ton style. Elles ne sont pas gonflables.', 'Hey <target>! Hör auf, sie anzubaggern, die sind nicht dein Typ. Die sind nicht aufblasbar.', '<target>！别勾搭了，他们不是充气娃娃。', '', '¡Oye, <target>! Deja de coquetear con ellos, no son tu tipo. No son inflables.', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1461', 'taunt', '<target> you’re so far outta your league, you’re playing a different sport.', '0', '0', '', '<target> tu es tellement dépassé, tu joues à un autre sport.', '<target>, du bist so weit aus deiner Liga, du spielst eine ganz andere Sportart.', '<target>你水平太菜，根本不在一个次元。', '', '<target> estás tan lejos de tu liga, estás jugando un deporte diferente.', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1462', 'taunt', 'You made a big mistake today <target>, you got out of bed.', '0', '0', '', '<target>, tu as commis une grosse erreur aujourd’hui en sortant du lit.', '<target>, du hast heute einen großen Fehler gemacht, du bist aus dem Bett gestiegen.', '<target>你今天犯了大错，就是起床。', '', 'Cometiste un gran error hoy <target>, te levantaste de la cama.', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1463', 'taunt', 'I wanna try turning into a horse, but I need help. I’ll be the front, you be yourself.', '0', '0', '', 'Je veux essayer de me transformer en cheval, mais j’ai besoin d’aide. Tu seras à l’avant, et je serai juste moi-même.', 'Ich will versuchen, mich in ein Pferd zu verwandeln, aber ich brauche Hilfe. Ich bin die Vorderseite und du bleibst du selbst.', '我想变成马，但需要帮忙。我当马头，你当马屁股。', '', 'Quiero intentar convertirme en un caballo, pero necesito ayuda. Yo seré el frente, tú mismo.', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1464', 'taunt', 'Can I borrow your face for a few days? My ass is going on holiday....', '0', '0', '', 'Je peux emprunter ton visage pendant quelques jours ? Mon derrière part en vacances...', 'Kann ich dein Gesicht für ein paar Tage leihen? Mein Hintern macht Urlaub...', '能借你脸几天吗？我屁股要度假…', '', '¿Me prestas tu cara por unos días? Mi culo se va de vacaciones...', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1465', 'taunt', 'I’d like to give you a going away present... First you do your part.', '0', '0', '', 'Je voudrais te donner un cadeau d’au revoir... Tout d’abord, toi tu fais ta part.', 'Ich würde dir gerne ein Abschiedsgeschenk machen... aber Zuerst machst du deinen Teil.', '我想送你临别礼物…先让我揍你一顿。', '', 'Me gustaría darte un regalo de despedida... Primero haz tu parte.', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1466', 'taunt', 'Before you came along we were hungry, Now we’re just fed up.', '0', '0', '', 'Avant ton arrivée, on avait faim. Maintenant, on en a juste assez.', 'Bevor du kamst, hatten wir Hunger. Jetzt ist uns schlecht.', '你来之前我们饿，现在只想吐。', '', 'Antes de que llegaras teníamos hambre, ahora estamos hartos', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1467', 'taunt', 'I like you. People say I have no taste, but I like you.', '0', '0', '', 'Je t’aime bien. Les gens disent que je n’ai pas de goût, mais je t’aime bien.', 'Ich mag dich. Die Leute sagen, ich hätte keinen Geschmack, aber ich mag dich.', '我喜欢你。别人说我品味差，但我喜欢你。', '', 'Me gustas. La gente dice que no tengo gusto, pero me gustas.', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1468', 'taunt', 'I think you have an inferiority complex, but that’s okay, it’s justified.', '0', '0', '', 'Je pense que tu as un complexe d’infériorité, mais il n’y a pas de problème, c’est justifié.', 'Ich glaube, du hast einen Minderwertigkeitskomplex, aber das ist okay, der ist berechtigt.', '我觉得你有自卑情结，不过也合理。', '', 'Creo que tienes complejo de inferioridad, pero está bien, está justificado', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1469', 'taunt', 'Hence rotten thing! Or I shall shake thy bones out of thy garments.', '0', '0', '', 'Miserable vermine! Sinon, je vais te secouer jusqu’à ce que tes os sortent de tes vêtements.', 'Fort mit dir, du faules Ding! Oder ich werde deine Gebeine aus deinen Kleidern schütteln.', '烂东西！不然我把你骨头从衣服里摇出来！', '', '¡Por lo tanto, cosa podrida! o te sacudiré los huesos de las vestiduras.', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1470', 'taunt', 'I can’t believe I’m wasting my time with you!', '0', '0', '', 'Je n’arrive pas à croire que je perds mon temps avec toi!', 'Ich kann nicht glauben, dass ich meine Zeit mit dir verschwende!', '不敢相信我在你身上浪费时间！', '', '¡No puedo creer que estoy perdiendo el tiempo contigo!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1471', 'taunt', 'I love it when someone insults me, it means I don’t have to be nice anymore.', '0', '0', '', 'j’adore quand quelqu’un m’insulte, ça veut dire que je n’ai plus besoin d’être gentil.', 'Ich liebe es, wenn mich jemand beleidigt. Das bedeutet, dass ich nicht mehr nett sein muss.', '我就喜欢别人骂我，这样我就不用装好人了。', '', 'Me encanta cuando alguien me insulta, significa que ya no tengo que ser amable', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1472', 'taunt', 'Thou leathern-jerkin, crystal-button, knot-pated, agatering, puke-stocking, caddis-garter, smooth-tongue, Spanish pouch!', '0', '0', '', 'Whoo, ça va swinguer, toi en ta peau de cuir, tes boutons de cristal, ton crâne noueux, tes chausses de vomi, tes jarretières en galon, ta langue de miel, et ta bourse espagnole !', 'Du Lederwams, Kristallknopf, Knotenpflaster, Achatring, Kotzstrumpf, Köcherfliegen-Strumpfband, Glattzunge, spanischer Beutel!', '你这皮背心、水晶扣、疙瘩头、玛瑙戒指、呕吐袜、毛线袜带、油嘴滑舌的西班牙钱袋！', '', '¡Tú, jubón de cuero, botón de cristal, anudado, ágata, medias de vómito, liga de caddis, lengua suave, bolsa española!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1473', 'taunt', 'Thou qualling bat-fowling malt-worm!', '0', '0', '', 'Espèce de vermine chauve-souris qui infeste l’orge maltée!', 'Du quälender Fledermausvogel-Malzwurm!', '你这尖叫的捕蝙蝠酒鬼！', '', '¡Tú, gusano de malta cazador de murciélagos!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1474', 'taunt', 'Thou art truely an idol of idiot-worshippers!', '0', '0', '', 'Tu es vraiment l’idole des adorateurs d’idiots!', 'Du bist wahrlich das Idol der Idiotenanbeter!', '你真是弱智崇拜的偶像！', '', '¡Eres verdaderamente un ídolo de los adoradores de idiotas!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1475', 'taunt', 'Thou misbegotten knotty-pated wagtail!', '0', '0', '', 'Espèce de galopin au cerveau embrouillé!', 'Du missratene, knotige Bachstelze!', '你这杂种木头脑袋的鹡鸰！', '', '¡Maldito lavandero nudoso!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1476', 'taunt', 'Thou whoreson mandrake, thou art fitter to be worn in my cap than to wait at my heels!', '0', '0', '', '', 'Du Hurensohn Alraune, es ist besser für dich, in meiner Mütze getragen zu werden, als hinter mir zu lauern!', '你这娼妓生的曼德拉草，更适合插我帽子上而不是跟在我脚后！', '', '¡Hijo de puta mandrágora, eres mejor para que te lleve en mi gorra que para que me pise los talones!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1477', 'taunt', 'You! You scullion! You rampallian! You fustilarian! I’ll tickle your catastrophe!', '0', '0', '', 'Toi! Toi l’écuyer! Toi le gredin! Toi le vaurien! Je vais titiller ta catastrophe!', 'Du! Du Küchenjunge! Du Randalierer! Du Fäustling! Ich werde eine Katastrophe auslösen!', '你！你这贱厨！恶棍！臭东西！我要挠死你！', '', '¡Tú! ¡Scullion! ¡Ramaliano! ¡Fustilarista! ¡Te haré cosquillas en tu catástrofe!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1478', 'taunt', 'Oh <target>! Thou infectious ill-nurtured flax-wench!', '0', '0', '', 'Oh <target>! Toi, vilaine lavandière malveillante et infecte!', 'Oh <target>! Du ansteckendes, schlecht gepflegtes Flachsweib!', '<target>！你这传染病的没教养的亚麻婊！', '', '¡Oh, <target>! ¡Tú, contagiosa moza del lino mal educada!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1479', 'taunt', 'We leak in your chimney, <target>!', '0', '0', '', 'On fuit dans ta cheminée, <target>!', 'Wir haben ein Leck in deinem Schornstein, <target>!', '<target>！我们在你烟囱里漏水！', '', '¡Tenemos una fuga en tu chimenea, <target>!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1480', 'taunt', 'Oh thou bootless fen-sucked canker-blossom!', '0', '0', '', 'Oh mon impuissant aspiré par les marais, fleur de chancre!', 'Oh du nutzlose, vom Moor ausgesaugte Krebsblüte!', '哦你这无用的沼泽吸食的溃烂花！', '', '¡Oh tú, flor de cancro chupada por el pantano sin botas!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1481', 'taunt', 'Were I like thee I’d throw away myself!', '0', '0', '', 'Si j’étais comme toi, je me jetterais en l’air !', 'Wäre ich wie du, würde ich mich selbst wegwerfen!', '我要是像你，早自杀了！', '', '¡Si yo fuera como tú, me tiraría a la basura!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1482', 'taunt', 'O teach me <target>, how I should forget to think!', '0', '0', '', 'Oh, enseigne-moi, <target>, comment oublier de trop réfléchir!', 'O <target> lehre mich, wie ich vergessen kann zu Denken!', '<target>教我怎么停止思考吧！', '', '¡Oh, enséñame <target>, cómo debo olvidarme de pensar!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1483', 'taunt', 'Truly thou art damned, like an ill-roasted egg, all on one side!', '0', '0', '', 'Franchement, tu es foutu, comme un œuf mal cuit, tout d’un côté!', 'Wahrlich, du bist verdammt, wie ein schlecht gebratenes Ei, alles auf einer Seite!', '你真是该死，像烤焦的鸡蛋，一边糊！', '', '¡Verdaderamente estás condenado, como un huevo mal asado, todo de un lado!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1484', 'taunt', 'You starvelling, you eel-skin, you dried neat’s-tongue, you bull’s-pizzle, you stock-fish- O for breath to utter what is like thee!! -you tailor’s-yard, you sheath, you bow-case, you vile standing tuck!', '0', '0', '', '', 'Du Verhungernder, du Aalhaut, du vertrocknete Rinderzunge, du Ochsenziemer, du Stockfisch – oh, hätte ich Atem, um auszusprechen, was dir gleicht!! – du Schneiderlein, du Schwertscheide, du Bogenfutteral, du schäbiges Stehaufmännchen!', '你这饿鬼、鳗鱼皮、干牛舌、牛鞭、咸鱼——我喘不过气来骂你！！——你这裁缝尺、刀鞘、弓盒、肮脏的直立褶裥！', '', 'Estás muerto de hambre, piel de anguila, te secaste la lengua limpiamente, toro-pizzle, pescado-O para respirar pronunciar lo que es como tú !! ¡Tú, sastrería, vaina, estuche de arco, vil flaco de pie!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1485', 'taunt', 'Fie! Drop thee into the rotten mouth of Death!', '0', '0', '', 'Que le diable t’emporte dans la gueule pourrie de la Mort!', 'Pfui! Wirf dich in den faulen Rachen des Todes!', '呸！让你烂在死神嘴里！', '', '¡Fie! ¡Déjate caer en la podrida boca de la Muerte!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1486', 'taunt', '<target>, you are a fishmonger!', '0', '0', '', '<target>, tu es poissonnier!', '<target>, du bist ein Fischhändler!', '<target>，你就是个鱼贩子！', '', '<target>, ¡eres un pescadero!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1487', 'taunt', 'I shall live to knock thy brains out!', '0', '0', '', 'Je vivrai pour te cogner le cerveau!', 'Ich lebe, um dir den Schädel einzuschlagen!', '我要活到敲碎你脑壳那天！', '', '¡Viviré para romperte los sesos!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1488', 'taunt', 'Most shallow are you, <target>!! Thou art worms-meat in respect of a good piece of flesh, indeed!!', '0', '0', '', 'Comme tu es superficiel <target>!! Tu n’es que de la chair à vers comparé à un bon morceau de viande, en effet!!', 'Du bist wirklich sehr oberflächlich, <target>!! Im Vergleich zu einem guten Stück Fleisch bist du wahrlich Wurmversäuchtes Fleisch!!', '<target>你肤浅！！和好肉相比你只配喂虫！！', '', '¡¡Eres el más superficial, <target>!! ¡Eres carne de gusano con respecto a un buen trozo de carne, de hecho!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1489', 'taunt', 'Vile wretch! O <target>, thou odiferous hell-hated pignut!', '0', '0', '', 'Misérable vermine! Ô <target>, toi l’infâme pignouf puant des enfers!', 'Abscheulicher Schurke! O <target>, du stinkender, höllisch verhasster Schweinshund!', '卑鄙小人！<target>你这地狱都嫌臭的花生！', '', '¡Miserable vil! ¡Oh, <target>, fétido cerdo odiado por el infierno!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1490', 'taunt', '<target>! Thy kiss is as comfortless as frozen water to a starved snake!', '0', '0', '', '<target>! Ton baiser est aussi réconfortant que de l’eau gelée pour un serpent affamé!', '<target>! Dein Kuss ist für eine ausgehungerte Schlange so trostlos wie gefrorenes Wasser!', '<target>！你的吻像冰水对饿蛇一样无情！', '', '<target>! ¡Tu beso es tan desconsolador como el agua helada para una serpiente hambrienta!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1491', 'taunt', 'I scorn you, scurvy companion. What, you poor, base, rascally, cheating, lack-linen mate! Away, you moldy rogue, away!', '0', '0', '', 'Je vous méprise, misérable compagnon. Quoi, toi, pauvre, vil, scélérat, tricheur, compagnon usé de toile! Déguerpisse, espèce de coquin moisissure, déguerpisse!', 'Ich verachte dich, schäbiger Geselle. Was, du armer, gemeiner, schurkischer, betrügerischer, leinenloser Kumpel? Weg, du schimmeliger Schurke, weg!', '我鄙视你，坏血病同伴。你这穷酸、卑劣、流氓、骗子、没衬衫的伙计！滚，发霉的恶棍，滚！', '', 'Te desprecio, compañero escorbuto. ¡Qué, pobre, vil, pícaro, tramposo, compañero falto de lino! ¡Fuera, mohoso granuja, fuera!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1492', 'taunt', 'Out of my sight! Thou dost infect my eyes <target>!', '0', '0', '', 'Hors de ma vue! Tu infectes mes yeux <target>!', 'Aus meinen Augen! Du infizierst meine Augen <target>!', '滚出我视线！<target>你污染我眼睛！', '', '¡Fuera de mi vista! ¡Me infectas los ojos <target>!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1493', 'taunt', 'PLAY TIME!!!!', '0', '0', '', 'L’HEURE DE LA MORT !', 'SPIELZEIT!!!', '开打时间到！！！！', '', '¡¡¡HORA DE JUGAR!!!!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1494', 'taunt', 'None shall pass!', '0', '0', '', 'Vous ne passerez pas !', 'Keiner kommt durch!', '此路不通！', '', '¡Ninguno pasará!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1495', 'taunt', 'We’re under attack! A vast, ye swabs! Repel the invaders!', '0', '0', '', 'Nous sommes attaqués! Visez bien, bande de moussaillons! Repoussez les envahisseurs!', 'Wir werden angegriffen! Ein gewaltiger Angriff, ihr Wichser! Schlagt die Eindringlinge zurück!', '我们被攻击了！全体船员！击退入侵者！', '', '¡Estamos bajo ataque! ¡Un vasto, hisopos! ¡Repeler a los invasores!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1496', 'taunt', 'None may challenge the Brotherhood!', '0', '0', '', 'Personne ne peut défier la Confrérie!', 'Niemand darf die Bruderschaft herausfordern!', '无人能挑战兄弟会！', '', '¡Nadie puede desafiar a la Hermandad!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1497', 'taunt', 'Foolsss...Kill the one in the dress!', '0', '0', '', 'Imbéciles... Tuez celui en robe!', 'Narren ... bringt die in den Kleidern um!', '蠢货…先杀穿裙子的那个！', '', 'Tontosss... ¡Matad al del vestido!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1498', 'taunt', 'I’ll feed your soul to Hakkar himself! ', '0', '0', '', 'Je vais nourrir ton âme à Hakkar lui-même!', 'Ich werde Hakkar persönlich mit deiner Seele füttern!', '我要把你的灵魂喂给哈卡！', '', '¡Le daré de comer con tu alma al mismísimo Hakkar! ', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1499', 'taunt', 'Pride heralds the end of your world! Come, mortals! Face the wrath of the <randomfaction>!', '0', '0', '', '<randomfaction> m’apporte une grande fierté! Venez, mortels ! Affrontez la colère de <randomfaction>!', 'Stolz läutet das Ende eurer Welt ein! Kommt, Sterbliche! Stellt euch dem Zorn der <randomfaction>!', '傲慢将终结你们的世界！来吧凡人！面对<randomfaction>的怒火！', '', '¡El orgullo anuncia el fin de tu mundo! ¡Venid, mortales! ¡Enfréntate a la ira de la <facción aleatoria>!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1500', 'taunt', 'All my plans have led to this!', '0', '0', '', 'Tous mes projets ont mené à cela!', 'Alle meine Pläne haben hierher geführt!', '我所有计划都是为了这一刻！', '', '¡Todos mis planes me han llevado a esto!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1501', 'taunt', 'Ahh! More lambs to the slaughter!', '0', '0', '', 'Oh non! Encore des agneaux pour l’abattoir!', 'Ahh! Noch mehr Lämmer zur Schlachtbank!', '啊！更多待宰羔羊！', '', '¡Ahh! ¡Más corderos al matadero!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1502', 'taunt', 'Another day, another glorious battle!', '0', '0', '', 'Une autre journée, une autre bataille glorieuse !', 'Ein neuer Tag, eine neue glorreiche Schlacht!', '又是新的一天，又是一场荣耀之战！', '', '¡Otro día, otra batalla gloriosa!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1503', 'taunt', 'So, business... or pleasure?', '0', '0', '', 'Alors, affaires... ou plaisir ?', 'Also, geschäftlich … oder privat?', '那么，是来办事…还是找乐子？', '', 'Entonces, ¿negocios... o placer?', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1504', 'taunt', 'You are not prepared!', '0', '0', '', 'Tu n’es pas prêt!', 'Du bist nicht vorbereitet!', '你们还没准备好！', '', '¡No estás preparado!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1505', 'taunt', 'The <randomfaction>’s final conquest has begun! Once again the subjugation of this world is within our grasp. Let none survive! ', '0', '0', '', 'La dernière conquête de <randomfaction> a commencé! Encore une fois, la soumission de ce monde est à portée de main. Que personne ne survive!', 'Die letzte Eroberung der <randomfaction> hat begonnen! Erneut liegt die Unterwerfung dieser Welt in unserer Hand. Lasst niemanden überleben!', '<randomfaction>的最终征服开始了！再次让世界臣服。不留活口！', '', '¡La conquista final de <randomfaction> ha comenzado! Una vez más, la subyugación de este mundo está a nuestro alcance. ¡Que nadie sobreviva! ', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1506', 'taunt', 'Your death will be a painful one. ', '0', '0', '', 'Ta mort sera une douloureuse.', 'Dein Tod wird schmerzhaft sein.', '你的死亡将充满痛苦。', '', 'Tu muerte será dolorosa. ', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1507', 'taunt', 'Cry for mercy! Your meaningless lives will soon be forfeit. ', '0', '0', '', 'Pleurez miséricorde! Vos vies insignifiantes seront bientôt perdues.', 'Fleht um Gnade! Eure bedeutungslosen Leben werden bald enden.', '哭求怜悯吧！你们毫无意义的人生即将终结。', '', '¡Llora por piedad! Sus vidas sin sentido pronto se perderán. ', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1508', 'taunt', 'Abandon all hope! The <randomfaction> has returned to finish what was begun so many years ago. This time there will be no escape! ', '0', '0', '', 'Abandonne tout espoir! La <randomfaction> est de retour pour finir ce qui a été commencé il y a tant d’années. Cette fois, il n’y aura pas d’échappatoire!', 'Gebt alle Hoffnung auf! Die <randomfaction> ist zurückgekehrt, um zu beenden, was vor so vielen Jahren begonnen wurde. Dieses Mal gibt es kein Entkommen!', '放弃希望吧！<randomfaction>归来完成多年前的伟业。这次无人能逃！', '', '¡Abandona toda esperanza! La <randomfaction> ha regresado para terminar lo que comenzó hace tantos años. ¡Esta vez no habrá escapatoria! ', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1509', 'taunt', 'Alert! You are marked for Extermination! ', '0', '0', '', 'Alerte ! Vous êtes désigné pour extermination !', 'Alarm! Du bist zur Auslöschung markiert!', '警报！你已被标记清除！', '', '¡Alerta! ¡Estás marcado para el exterminio! ', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1510', 'taunt', 'The <subzone> is for guests only...', '0', '0', '', 'Le <subzone> est réservé aux invités uniquement...', 'Die <subzone> ist nur für Gäste...', '<subzone>只接待贵宾…', '', 'La <subzone> es solo para invitados...', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1511', 'taunt', 'Ha ha ha! You are hopelessly outmatched!', '0', '0', '', 'Ha ha ha! Tu es totalement dépassé!', 'Ha ha ha! Du bist hoffnungslos unterlegen!', '哈哈哈！你们毫无胜算！', '', '¡Ja, ja, ja! ¡Estás irremediablemente superado!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1512', 'taunt', 'I will crush your delusions of grandeur! ', '0', '0', '', 'Je vais briser tes illusions de grandeur!', 'Ich werde deinen Größenwahn zerschmettern!', '我要粉碎你们的狂妄幻想！', '', '¡Aplastaré tus delirios de grandeza! ', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1513', 'taunt', 'Forgive me, for you are about to lose the game.', '0', '0', '', 'Pardonnez-moi, mais vous êtes sur le point de perdre la partie.', 'Verzeih mir, aber du wirst dieses Spiel verlieren.', '原谅我，因为你即将输掉游戏。', '', 'Perdóname, porque estás a punto de perder el juego.', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1514', 'taunt', 'Struggling only makes it worse.', '0', '0', '', 'Se battre ne fait qu’empirer les choses.', 'Widerstand macht es nur schlimmer.', '挣扎只会更糟。', '', 'La lucha solo lo empeora.', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1515', 'taunt', 'Vermin! Leeches! Take my blood and choke on it!', '0', '0', '', 'Créatures immondes ! Sangsues ! Prenez mon sang et étouffez-y !', 'Ungeziefer! Blutegel! Nehmt mein Blut und erstickt daran!', '害虫！水蛭！喝我的血噎死吧！', '', '¡Alimañas! ¡Sanguijuelas! ¡Toma mi sangre y atragantate con ella!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1516', 'taunt', 'Not again... NOT AGAIN!', '0', '0', '', 'Pas encore... PAS ENCORE !', 'Nicht schon wieder... NICHT SCHON WIEDER!', '别再来…别再来！', '', 'No otra vez... ¡NO OTRA VEZ!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1517', 'taunt', 'My blood will be the end of you!', '0', '0', '', 'Mon sang sera ta fin!', 'Mein Blut wird dein Ende sein!', '我的血将是你的终结！', '', '¡Mi sangre será tu fin!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1518', 'taunt', 'Good, now you fight me!', '0', '0', '', 'Bien, maintenant combat moi !', 'Gut, jetzt kämpfst du gegen mich!', '很好，现在来战！', '', 'Bien, ¡ahora pelea conmigo!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1519', 'taunt', 'Get da move on, guards! It be killin’ time!', '0', '0', '', 'Allez, les gardes, on se presse! C’est l’heure de tuer!', 'Los, Wachen! Zeit zu töten!', '动起来，卫兵！杀戮时间到！', '', '¡Muévanse, guardias! ¡Será para matar el tiempo!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1520', 'taunt', 'Don’t be delayin’ your fate. Come to me now. I make your sacrifice quick.', '0', '0', '', 'Ne retarde pas ton destin. Viens à moi maintenant. Je rends ton sacrifice rapide.', 'Verzögere dein Schicksal nicht. Komm jetzt zu mir. Ich mache dein Ende schnell.', '别拖延你的命运。现在过来，我让你死得痛快。', '', 'No demores tu destino. Ven a mí ahora. Hago que tu sacrificio sea rápido.', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1521', 'taunt', 'You be dead soon enough!', '0', '0', '', 'Tu seras bientôt mort !', 'Du wirst bald tot sein!', '你很快就死！', '', '¡Estarás muerto lo suficientemente pronto!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1522', 'taunt', 'Mua-ha-ha!', '0', '0', '', 'Mua-ha-ha!', 'Mua-ha-ha!', '木哈哈！', '', '¡Mua-ja-ja!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1523', 'taunt', 'I be da predator! You da prey...', '0', '0', '', 'Je suis le prédateur! Tu es la proie...', 'Ich bin der Jäger! Du bist die Beute...', '我是猎手！你是猎物…', '', '¡Soy un depredador! Eres presa...', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1524', 'taunt', 'You gonna leave in pieces!', '0', '0', '', 'Tu vas finir en morceaux !', 'Du wirst diesen Ort in Stücken verlassen!', '你会碎成渣离开！', '', '¡Te vas a ir en pedazos!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1525', 'taunt', 'Death comes. Will your conscience be clear? ', '0', '0', '', 'La mort arrive. Est-ce que ta conscience sera claire ?', 'Der Tod kommt. hast du ein reines Gewissen?', '死亡降临。你良心清白吗？', '', 'La muerte llega. ¿Tu conciencia estará limpia? ', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1526', 'taunt', 'Your behavior will not be tolerated.', '0', '0', '', 'Votre comportement ne sera pas toléré.', 'Dein Verhalten wird nicht toleriert.', '你的行为不可容忍。', '', 'Tu comportamiento no será tolerado', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1527', 'taunt', 'The Menagerie is for guests only.', '0', '0', '', 'La Ménagerie est réservée aux invités seulement.', 'Die Menagerie ist nur für Gäste.', '兽栏只接待贵宾。', '', 'The Menagerie es solo para invitados', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1528', 'taunt', 'Hmm, unannounced visitors, Preparations must be made... ', '0', '0', '', 'Des visiteurs non annoncés, il me faut faire des préparatifs...', 'Hmm, unangekündigte Besucher, Vorbereitungen müssen getroffen werden...', '嗯，不速之客，得准备下…', '', 'Hmm, visitantes inesperados, se deben hacer preparativos... ', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1529', 'taunt', 'Hostile entities detected. Threat assessment protocol active. Primary target engaged. Time minus thirty seconds to re-evaluation.', '0', '0', '', 'Entités hostiles détectées. Protocole d’évaluation des menaces activé. Cible principale engagée. Temps moins trente secondes avant réévaluation.', 'Feindliche Einheiten entdeckt. Bedrohungsbewertungsprotokoll aktiv. Primärziel angegriffen. Zeit bis zur Neubewertung: minus dreißig Sekunden.', '检测到敌对实体。威胁评估协议启动。主要目标锁定。30秒后重新评估。', '', 'Entidades hostiles detectadas. Protocolo de evaluación de amenazas activo. Objetivo principal comprometido. Tiempo menos treinta segundos para la reevaluación.', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1530', 'taunt', 'New toys? For me? I promise I won’t break them this time!', '0', '0', '', 'De nouveaux jouets ? Pour moi ? Je te promets que cette fois, je ne les casserai pas !', 'Neue Spielzeuge? Für mich? Ich verspreche, ich werde sie dieses Mal nicht kaputt machen!', '新玩具？给我的？这次保证不弄坏！', '', '¿Juguetes nuevos? ¿Para mi? ¡Te prometo que no los romperé esta vez!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1531', 'taunt', 'I’m ready to play!', '0', '0', '', 'Je suis prêt à jouer !', 'Ich bin bereit zu spielen!', '我准备好开玩了！', '', '¡Estoy listo para jugar!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1532', 'taunt', 'Shhh... it will all be over soon.', '0', '0', '', 'Chut... tout sera bientôt fini.', 'Shhh... es wird bald vorbei sein.', '嘘…很快就结束了。', '', 'Shhh... todo terminará pronto.', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1533', 'taunt', 'Aaaaaughibbrgubugbugrguburgle!', '0', '0', '', 'Aaaaaughibbrgubugbugrguburgle!', 'Aaaaaughibbrgubugbugrguburgle!', '啊啊啊叽里咕噜！（鱼人语）', '', '¡Aaaaaughibbrgubugbugrguburgle!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1534', 'taunt', 'RwlRwlRwlRwl!', '0', '0', '', 'RwlRwlRwlRwl!', 'RwlRwlRwlRwl!', '噜噜噜噜！（鱼人语）', '', 'RwlRwlRwlRwl!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1535', 'taunt', 'You too, shall serve!', '0', '0', '', 'Toi aussi, tu serviras !', 'Auch du wirst dienen!', '你，也将臣服！', '', '¡Tú también, debes servir!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1536', 'taunt', 'Tell me... tell me everything!  Naughty secrets! I’ll rip the secrets from your flesh!', '0', '0', '', 'Dis-moi... dis-moi tout ! Les petits secrets coquins ! Je vais arracher les secrets de ta chair !', 'Sag mir... sag mir alles! Schmutzige Geheimnisse! Ich werde dir deine Geheimnisse aus deinem Fleisch reißen!', '告诉我…全部！肮脏的秘密！我要从你血肉中撕出秘密！', '', 'Cuéntame... ¡cuéntame todo! ¡Secretos traviesos! ¡Arrancaré los secretos de tu carne!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1537', 'taunt', 'Prepare yourselves, the bells have tolled! Shelter your weak, your young and your old! Each of you shall pay the final sum! Cry for mercy, the reckoning has come!', '0', '0', '', 'Préparez-vous, les cloches ont sonné ! Protégez vos faibles, vos jeunes et vos anciens ! Chacun d’entre vous paiera le prix final ! Pleurez miséricorde, l’heure du jugement est arrivée!', 'Bereitet euch vor, die Glocken haben geläutet! Schützt eure Schwachen, eure Jungen und eure Alten! Jeder von euch wird den endgültigen Preis zahlen! Fleht um Gnade, die Abrechnung ist gekommen!', '准备好吧，丧钟已响！保护老弱妇孺！你们都将付出代价！哭求宽恕吧，清算已至！', '', '¡Prepárense, las campanas han doblado! ¡Abriga a tus débiles, a tus jóvenes ya tus viejos! ¡Cada uno de ustedes pagará la suma final! Clama por misericordia, el ajuste de cuentas ha llegado!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1538', 'taunt', 'Where in Bonzo’s brass buttons am I?', '0', '0', '', 'Où diable suis-je?', 'Wo zur Hölle bin ich?', '我这是在邦佐的黄铜纽扣里吗？', '', '¿Dónde estoy en los botones de latón de Bonzo?', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1539', 'taunt', 'I can bear it no longer! Goblin King! Goblin King! Wherever you may be! Take this <target> far away from me!', '0', '0', '', 'Je n’en peux plus! Roi des Gobelins! Roi des Gobelins! Où que tu sois! Emmène cette %cible% loin de moi!', 'Ich ertrage es nicht mehr! Goblinkönig! Goblinkönig! Wo immer du bist! Nimm diesen <target> weit weg von mir!', '我受不了了！地精王！地精王！不管你在哪！把<target>从我身边带走！', '', '¡No puedo soportarlo más! ¡Rey de los duendes! ¡Rey de los duendes! ¡WHERE quiera que estés! ¡Lleva a este <target> lejos de mí!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1540', 'taunt', 'You have thirteen hours in which to solve the labyrinth, before your baby brother becomes one of us... forever.', '0', '0', '', 'Tu as treize heures pour résoudre le labyrinthe, avant que ton petit frère ne devienne l’un d’entre nous... pour toujours.', 'Du hast dreizehn Stunden, um das Labyrinth zu lösen, bevor dein kleiner Bruder einer von uns wird... für immer.', '你还有十三小时解开迷宫，否则你弟弟将永远成为我们的一员…', '', 'Tienes trece horas para resolver el laberinto, antes de que tu hermanito se convierta en uno de nosotros... para siempre', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1541', 'taunt', 'So, the <subzone> is a piece of cake, is it? Well, let’s see how you deal with this little slice... ', '0', '0', '', 'Alors, la <subzone> est du gâteau, vous dites? Hmm, voyons comment vous vous en sortez avec cette petite portion...', 'Also, die <subzone> ist ein Kinderspiel, ja? Nun, sehen wir mal, wie du mit diesem kleinen Stück klarkommst...', '<subzone>很简单是吧？看看你怎么处理这一小块…', '', 'Entonces, la <subzone> es pan comido, ¿verdad? Bueno, veamos cómo lidias con esta pequeña porción... ', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1542', 'taunt', 'Back off, I’ll take you on, headstrong to take on anyone, I know that you are wrong, and this is not where you belong', '0', '0', '', 'Alors, recule, je vais m’occuper de toi, déterminé à affronter n’importe qui, je sais que tu as tort, et ce n’est pas là que tu appartiens', 'Zurück, ich nehme dich auf, entschlossen, es mit jedem aufzunehmen, ich weiß, dass du falsch liegst, und das ist nicht der Ort, an den du gehörst', '退后，我来对付你，固执地挑战所有人，我知道你错了，这里不属于你', '', 'Atrás, te enfrentaré, testarudo para enfrentar a cualquiera, sé que estás equivocado, y este no es el lugar al que perteneces', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1543', 'taunt', 'Show me whatcha got!', '0', '0', '', 'Montre-moi ce que t’as dans le ventre!', 'Zeig mir, was du drauf hast!', '让我看看你的本事！', '', '¡Muéstrame lo que tienes!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1544', 'taunt', 'To the death!', '0', '0', '', '% Sorry, I can’t translate that.', 'Bis zum Tod!', '至死方休！', '', '¡Hasta la muerte!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1545', 'taunt', 'Twin blade action, for a clean close shave every time.', '0', '0', '', 'Lame jumelle, pour un rasage de près impeccable à chaque fois.', 'Doppelklingenaktion, für eine saubere Rasur jedes Mal.', '双刀出击，每次都能剃干净。', '', 'Acción de cuchilla doble, para un afeitado limpio y apurado en todo momento.', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1546', 'taunt', 'Bring it on!', '0', '0', '', 'Allez, viens ici !', 'Los geht’s!', '放马过来！', '', '¡Adelante!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1547', 'taunt', 'You’re goin’ down!', '0', '0', '', 'Tu vas tomber !', 'Du gehst unter!', '你要完蛋了！', '', '¡Vas a caer!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1548', 'taunt', 'Stabby stab stab!', '0', '0', '', 'Stabby stab stab!', 'Stech, stech, stech!', '捅捅捅！', '', '¡Puñalada puñalada puñalada!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1549', 'taunt', 'Let’s get this over quick, time is mana.', '0', '0', '', 'Finissons-en vite , le temps c’est du mana.', 'Lass uns das schnell beenden, Zeit ist Mana.', '速战速决，时间就是法力。', '', 'Terminemos con esto rápido, el tiempo es maná.', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1550', 'taunt', 'I do not think you realise the gravity of your situation.', '0', '0', '', 'Tu ne réalise pas encore la gravité de ta situation.', 'Ich glaube nicht, dass du die Schwere deiner Lage begreifst.', '我觉得你没意识到情况多严重。', '', 'No creo que te des cuenta de la gravedad de tu situación.', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1551', 'taunt', 'I will bring honor to my family and my kingdom!', '0', '0', '', 'Je vais apporter honneur à ma famille et à mon royaume!', 'Ich werde meiner Familie und meinem Königreich Ehre bringen!', '我将为家族和王国带来荣耀！', '', '¡Llevaré honor a mi familia y mi reino!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1552', 'taunt', 'Light, give me strength!', '0', '0', '', 'Lumière, donne-moi de la force!', 'Licht, gib mir Kraft!', '圣光，赐予我力量！', '', '¡Luz, dame fuerza!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1553', 'taunt', 'My church is the field of battle - time to worship...', '0', '0', '', 'Mon terrain de bataille, c’est mon église - il est temps de rendre hommage...', 'Das Schlachtfeld ist meine Kirche - Zeit für die Anbetung...', '我的教堂是战场——该祈祷了…', '', 'Mi iglesia es el campo de batalla - hora de adorar...', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1554', 'taunt', 'I hold you in contempt...', '0', '0', '', 'Je te méprise...', 'Ich verachte dich...', '我鄙视你…', '', 'Te tengo en desacato...', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1555', 'taunt', 'Face the hammer of justice!', '0', '0', '', 'Affronte le marteau de la justice!', 'Stell dich dem Hammer der Gerechtigkeit!', '面对正义之锤！', '', '¡Enfréntate al martillo de la justicia!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1556', 'taunt', 'Prove your worth in the test of arms under the Light!', '0', '0', '', 'Prouve ta valeur dans le test des armes sous la Lumière!', 'Beweise deinen Wert in der Prüfung der Waffen unter dem Licht!', '在圣光下的武艺试炼中证明你的价值！', '', '¡Demuestra tu valía en la prueba de las armas bajo la Luz!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1557', 'taunt', 'All must fall before the might and right of my cause, you shall be next!', '0', '0', '', 'Tous doivent tomber devant la puissance et la justesse de ma cause, tu seras le prochain!', 'Alle müssen vor der Macht und dem Recht meiner Sache fallen, du bist der Nächste!', '在我的正义伟力前，万物皆倒，你是下一个！', '', 'Todo debe caer ante el poder y el derecho de mi causa, ¡tú serás el próximo!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1558', 'taunt', 'Prepare to die!', '0', '0', '', 'Prépare-toi à mourir!', 'Mach dich bereit zu sterben!', '准备受死！', '', '¡Prepárate para morir!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1559', 'taunt', 'The beast with me is nothing compared to the beast within...', '0', '0', '', 'La bête qui est avec moi n’est rien comparée à la bête qui est en moi...', 'Die Bestie an meiner Seite ist nichts im Vergleich zur Bestie in mir...', '与我同行的野兽远不及我内心的野兽…', '', 'La bestia conmigo no es nada comparada con la bestia interior...', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1560', 'taunt', 'Witness the firepower of this fully armed huntsman!', '0', '0', '', 'Découvrez la puissance de feu de ce chasseur entièrement armé!', 'Erlebe die Feuerkraft dieses voll bewaffneten Jägers!', '见证全副武装猎人的火力吧！', '', '¡Sea testigo de la potencia de fuego de este cazador completamente armado!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1561', 'critical health', 'Heal me! Quick!', '0', '0', '', 'Je vais te soigner tout de suite !', 'Heil mich! Schnell!', '奶我！快！', '', '¡Cúrame! ¡Rápido!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1562', 'critical health', 'Almost dead! Heal me!', '0', '0', '', 'Presque mort ! Soignez-moi !', 'Fast tot! Heil mich!', '快死了！奶我！', '', '¡Estoy casi muerto! ¡Cúrame!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1563', 'critical health', 'Help! Heal me!', '0', '0', '', 'S’il te plaît, aide-moi! Soigne-moi!', 'Hilfe! Heil mich!', '救命！奶我！', '', '¡Ayuda! ¡Cúrame!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1564', 'critical health', 'Somebody! Heal me!', '0', '0', '', 'Quelqu’un ! Soigne-moi !', 'Irgendjemand! Heil mich!', '来人！奶我！', '', '¡Alguien! ¡Cúrame!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1565', 'critical health', 'Heal! Heal! Heal!', '0', '0', '', 'Guérir! Guérir! Guérir!', 'Heilung! Heilung! Heilung!', '奶！奶！奶！', '', '¡Curame! ¡Saname! ¡Socorro!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1566', 'critical health', 'I am dying! Heal! Aaaaarhg!', '0', '0', '', 'Je meurs! Au secours! Aaaaarhg!', 'Ich sterbe! Heilung! Aaaaarhg!', '我要死了！奶！啊啊啊！', '', '¡Me estoy muriendo! ¡Saname! ¡Aaaaarhg!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1567', 'critical health', 'Heal me!', '0', '0', '', 'Soigne moi !', 'Heil mich!', '奶我！', '', '¡Cúrame!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1568', 'critical health', 'I will die. I will die. I will die. Heal!', '0', '0', '', 'Je vais mourir. Je vais mourir. Je vais mourir. Soigne-moi !', 'Ich werde sterben. Ich werde sterben. Ich werde sterben. Heilung!', '我要死了。要死了。要死了。奶！', '', 'Voy a morir. Voy a morir. Voy a morir. ¡Saname!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1569', 'critical health', 'Healers, where are you? I am dying!', '0', '0', '', 'Healers, où êtes-vous? Je suis en train de mourir!', 'Heiler, wo seid ihr? Ich sterbe!', '治疗呢？我要死了！', '', 'Sanadores, ¿dónde estais? ¡Me estoy muriendo!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1570', 'critical health', 'Oh the pain. Heal me quick!', '0', '0', '', 'Oh la douleur. Guérissez-moi vite!', 'Oh, der Schmerz. Heil mich schnell!', '好痛。快奶我！', '', 'Ouch, qué dolor. ¡Cúrame rápido!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1571', 'low health', 'Need heal', '0', '0', '', 'Besoin de soins', 'Brauche Heilung', '要治疗', '', 'Necesito una cura', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1572', 'low health', 'Low health', '0', '0', '', 'Faible santé', 'Wenig Leben', '残血', '', 'Salud baja', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1573', 'low health', 'Drop a heal. Please.', '0', '0', '', 'HEAL. S’il te plaît.', 'Heilung bitte.', '给口奶，求你了。', '', 'Una sanación por favor.', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1574', 'low health', 'Could somebody drop a heal on me?', '0', '0', '', 'Est-ce que quelqu’un pourrait me soigner?', 'Kann mich jemand heilen?', '能给我口奶吗？', '', '¿Alguien podría curarme?', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1575', 'low health', 'Hey! Better heal me now than rez later', '0', '0', '', 'Salut! Mieux vaut me soigner maintenant que me ressusciter plus tard.', 'Hey! Heilt mich lieber jetzt als mich später zu wiederbeleben.', '嘿！现在奶比等下战复好', '', '¡Oye! Mejor curarme ahora que resucitarme después', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1576', 'low health', 'I am sorry. Need another heal', '0', '0', '', 'Je suis désolé. J’ai besoin d’une autre guérison.', 'Tut mir leid. Brauche nochmal Heilung.', '抱歉。还要口奶', '', 'Lo siento. Necesito otra curación', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1577', 'low health', 'Damn mobs. Heal me please', '0', '0', '', 'Maudits mobs. Guéris moi s’il te plait', 'Verdammte Mobs. Heilt mich bitte.', '怪真烦。奶我下', '', '¡Malditos bichos! ¡Una curita por favor!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1578', 'low health', 'One more hit and I am done for. Heal please', '0', '0', '', 'Un coup de plus et c’est fini. Guéris moi s’il te plait', 'Ein Treffer noch und ich bin erledigt. Heilung bitte.', '再挨一下我就没了。奶我', '', 'Un golpe más y estoy acabado. Cura por favor', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1579', 'low health', 'Are there any healers?', '0', '0', '', 'Y a-t-il des guérisseurs?', 'Gibt es hier Heiler?', '有治疗吗？', '', '¿Hay sanadores?', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1580', 'low health', 'Why do they always punch me in the face? Need heal', '0', '0', '', 'Pourquoi est-ce qu’ils me frappent toujours au visage? J’ai besoin de guérison', 'Warum schlagen sie mir immer ins Gesicht? Brauche Heilung.', '为啥总打我脸？要奶', '', '¿Por qué siempre me golpean en la cara? Necesito sanacion', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1581', 'low health', 'Can anybody heal me a bit?', '0', '0', '', 'Soignez moi, même juste un peu ?', 'Kann mich jemand ein bisschen heilen?', '能奶我一口吗？', '', '¿Alguien puede curarme un poco?', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1582', 'low mana', 'OOM', '0', '0', '', 'Plus de mana !', 'Kein Mana mehr!', '没蓝了', '', 'No tengo mana!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1583', 'low mana', 'I am out of mana', '0', '0', '', 'Je n’ai plus de mana', 'Ich habe kein Mana mehr', '我没蓝了', '', 'No tengo maná', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1584', 'low mana', 'Damn I wasted all my mana on this', '0', '0', '', 'Damn j’ai gaspillé toute ma mana sur ça.', 'Verdammt, ich habe mein ganzes Mana darauf verschwendet.', '靠，我把蓝全耗这上了', '', 'Me cago en todo! Malgasté todo mi maná enseguida', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1585', 'low mana', 'You should wait until I drink or regenerate my mana', '0', '0', '', 'Tu devrais attendre que je boive ou régénère ma mana.', 'Du solltest warten, bis ich trinke oder Mana regeneriere.', '等我喝水回蓝', '', 'Deberías esperar hasta que beba o regenere mi maná', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1586', 'low mana', 'Low mana', '0', '0', '', 'Bas niveau de mana.', 'Wenig Mana.', '蓝量低', '', 'Maná bajo', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1587', 'low mana', 'No mana. Again?', '0', '0', '', 'Pas de mana. Encore ?', 'Kein Mana. Schon wieder?', '又没蓝了？', '', 'Sin maná. ¿Otra vez?', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1588', 'low mana', 'Low mana. Wanna drink', '0', '0', '', 'Plus de mana, je prendrai bien un peu d eau', 'Kein Mana mehr, ich sollte etwas trinken.', '蓝少，想喝水', '', 'Maná bajo. Quiero beber', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1589', 'low mana', 'Do we have a vending machine? Out of mana again', '0', '0', '', 'Nous avons une machine distributrice ? Encore à court de mana.', 'Haben wir einen Automaten? Schon wieder kein Mana.', '有自动贩卖机吗？又没蓝了', '', '¿Tenemos una máquina expendedora? Sin maná otra vez', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1590', 'low mana', 'My mana is history', '0', '0', '', 'Mon mana est à sec.', 'Mein Mana ist Geschichte.', '蓝见底了', '', 'Mi maná es historia', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1591', 'low mana', 'I’d get some drinks next time. Out of mana', '0', '0', '', 'Je prendrai des verres la prochaine fois. Plus de mana.', 'Ich hole mir nächstes Mal ein paar Tränke. Kein Mana mehr.', '下次多带点水。没蓝了', '', '¡No tengo maná! Tengo que comprar bebidas la próxima vez...', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1592', 'low mana', 'Where is my mana?', '0', '0', '', 'Oh là là, désolé, mais je ne sais pas du tout où se trouve ta mana. As-tu vérifié tous tes sacs et tes poches? Peut-être que tu l’as laissé quelque part dans la maison ou dans ton sac à dos. Il est toujours embêtant de perdre quelque chose d’aussi précieux que sa mana, j’espère que tu vas la retrouver bientôt!', 'Wo ist mein Mana?', '我蓝呢？', '', '¿Dónde está mi maná?', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1593', 'low ammo', 'I have few <ammo> left!', '0', '0', '', 'Il ne me reste que quelques <ammo> !', 'Ich habe nur noch wenig <ammo>!', '<ammo>快用完了！', '', '¡Me quedan pocas <ammo>!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1594', 'low ammo', 'I need more <ammo>!', '0', '0', '', 'J’ai besoin de plus de <ammo>!', 'Ich brauche mehr <ammo>!', '需要更多<ammo>！', '', '¡Necesito más <ammo>!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1595', 'low ammo', '100 <ammo> left!', '0', '0', '', 'Il me reste 100 <ammo> !', 'Ich habe noch 100 <ammo> übrig!', '还剩100发<ammo>！', '', '¡Quedan 100 <ammo>!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1596', 'no ammo', 'That’s it! No <ammo>!', '0', '0', '', 'C’est ça! Pas de <ammo>!', 'Das war’s! Keine <ammo> mehr!', '完了！没<ammo>了！', '', '¡Eso es todo! ¡Sin <ammo>!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1597', 'no ammo', 'And you have my bow... Oops, no <ammo>!', '0', '0', '', 'Et vous avez mon arc... Oops, pas de <munitions> !', 'Und du hast meinen Bogen... Ups, keine <ammo>!', '还有我的弓…糟，没<ammo>了！', '', 'Y tú tienes mi arco... ¡Uy, sin <ammo>!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1598', 'no ammo', 'Need ammo!', '0', '0', '', 'Besoin de munitions !', 'Brauche Munition!', '需要弹药！', '', '¡Necesito munición!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1599', 'aoe', 'Oh god!', '0', '0', '', 'Oh mon Dieu!', 'Oh Gott!', '天啊！', '', '¡Oh, Dios!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1600', 'aoe', 'I am scared', '0', '0', '', 'Je suis effrayé.', 'Ich habe Angst.', '我怕了', '', 'Tengo miedo', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1601', 'aoe', 'We are done for', '0', '0', '', 'Nous sommes foutus.', 'Wir sind erledigt.', '我们完了', '', 'Hemos terminado', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1602', 'aoe', 'This is over', '0', '0', '', 'C’est terminé', 'Das war’s.', '结束了', '', 'Esto se acabó', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1603', 'aoe', 'This ends now', '0', '0', '', 'Cela se termine maintenant.', 'Das endet jetzt.', '到此为止', '', 'Esto termina ahora', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1604', 'aoe', 'Could somebody cast blizzard or something?', '0', '0', '', 'Est-ce que quelqu’un pourrait lancer une tempête de neige ou quelque chose du genre, s’il vous plaît?', 'Kann jemand Blizzard anrufen?', '谁能下个暴风雪啥的？', '', '¿Alguien podría lanzar ventisca o algo así?', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1605', 'aoe', 'Damn. The tank aggroed all the mobs around', '0', '0', '', 'Maudit tank a attiré tous les ennemis autour.', 'Verdammt. Der Tank hat alle Mobs um uns herum gepullt.', '靠，坦克拉了一堆怪', '', '¡Me cago en todo! El tanque atrajo a todos los mobs...', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1606', 'aoe', 'We gonna die. We gonna die. We gonna die.', '0', '0', '', 'On va mourir. On va mourir. On va mourir.', 'Wir werden sterben. Wir werden sterben. Wir werden sterben.', '我们要死了。要死了。要死了。', '', 'Vamos a morir. Vamos a morir. Vamos a morir.', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1607', 'aoe', 'Whoa! So many toys to play with', '0', '0', '', 'Oh là là ! Tellement de jouets avec lesquels jouer !', 'Wow! So viele Spielzeuge zum Spielen!', '哇！这么多玩具', '', '¡Vaya! Tantos juguetes con los que jugar', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1608', 'aoe', 'I gonna kill them all!', '0', '0', '', 'Je vais les tuer tous !', 'Ich werde sie alle töten!', '我要杀光他们！', '', '¡Voy a matarlos a todos!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1609', 'aoe', 'If the tank dies we are history', '0', '0', '', 'Si le tank meurt, c’est la fin pour nous.', 'Wenn der Tank stirbt, war es das für uns.', '坦克一死我们就完', '', 'Si el tanque muere somos historia', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1610', 'aoe', 'Aaaaaargh!', '0', '0', '', 'Aaaaaaah!', 'Aaaaaargh!', '啊啊啊！', '', '¡Aaaaaargh!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1611', 'aoe', 'LEEEEERROOOYYYYYYYYYYYY JENNKINNNSSSSSS!!!!!!!', '0', '0', '', 'LEEROOOOOOOYYYYYYYYYYY JENNKINNNSSSSSSS!!!!!!!', 'CAAAAAARL!!!!!!!', '李————罗————伊————杰————金————斯————！！！！！！', '', 'LEEEEERROOOYYYYYYYYYYYY JENNKINNNSSSSSS!!!!!!!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1612', 'aoe', 'Right. What do we have in AOE?', '0', '0', '', 'Alors, qu’est-ce qu’on a dans AOE?', 'Okay. Was haben wir für AOE?', '好吧，我们有什么AOE技能？', '', 'Claro. ¿Qué tenemos en AOE?', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1613', 'aoe', 'This gets interesting', '0', '0', '', 'Cela devient intéressant', 'Das wird interessant.', '变得有意思了', '', 'Esto se pone interesante', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1614', 'aoe', 'Cool. Get them in one place for a good flamestrike', '0', '0', '', 'Cool. Rassemble-les au même endroit pour un bon Coup de Flamme.', 'Cool. Bringt sie alle zusammen für einen ordentlichen Flammenstoß.', '酷。聚一起放烈焰风暴', '', 'Genial! Ponlos todos juntos para un buen ataque en area', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1615', 'aoe', 'Kill! Kill! Kill!', '0', '0', '', 'TUER! TUER! TUER!.', 'TÖTEN! TÖTEN! TÖTEN!', '杀！杀！杀！', '', '¡Matar! ¡Matar! ¡Matar!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1616', 'aoe', 'I think my pants are wet', '0', '0', '', 'Je crois que mon pantalon est mouillé.', 'Ich glaube, meine Hose ist nass.', '我感觉裤子湿了', '', 'Creo que mis pantalones están mojados', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1617', 'aoe', 'We are history', '0', '0', '', 'Nous sommes l’histoire.', 'Wir sind Geschichte.', '我们完了', '', 'Somos historia', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1618', 'aoe', 'I hope healers are ready. Leeeeroy!', '0', '0', '', 'J’espère que les heal sont prêt. Leeeeroy!', 'Ich hoffe, die Heiler sind bereit. CAAAAAARL!', '希望治疗准备好了。李罗伊！', '', 'Espero que los sanadores estén listos. ¡Leeeroy!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1619', 'aoe', 'I hope they won’t come for me', '0', '0', '', 'J’espère qu’ils ne viendront pas me chercher.', 'Ich hoffe, sie kommen nicht zu mir.', '希望他们别冲我来', '', 'Espero que no vengan por mí', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1620', 'aoe', 'Oh no. I can’t see at this slaugther', '0', '0', '', 'Oh non. Je ne peux pas regarder ce massacre.', 'Oh nein. Ich kann dieses Gemetzel nicht ansehen.', '哦不，这场屠杀我看不下去了', '', 'Oh, no. No puedo ver esta matanza', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1621', 'loot', 'I hope there will be some money', '0', '0', '', 'J’espère qu’il y aura de l’argent.', 'Ich hoffe, es gibt etwas Geld.', '希望有钱拿', '', 'Espero que haya algo de dinero...', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1622', 'loot', 'Loot! Loot!', '0', '0', '', 'Butin! Butin!', 'Beute! Beute!', '战利品！战利品！', '', '¡Botín! ¡Botín!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1623', 'loot', 'My precious', '0', '0', '', 'Mon précieux', 'Mein Schatz', '我的宝贝', '', 'Mi tesoro...', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1624', 'loot', 'I hope there is a shiny epic item waiting for me there', '0', '0', '', 'j’espère qu’il y a un objet épique brillant qui m’attend ici', 'Ich hoffe, dort wartet ein glänzendes episches Item auf mich.', '希望有闪亮的紫装在等我', '', 'Espero que haya un objeto épico brillante esperándome allí', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1625', 'loot', 'I have deep pockets and bags', '0', '0', '', 'J’ai de grandes poches et des sacs profonds.', 'Ich habe tiefe Taschen und große Beutel.', '我包大得很', '', 'Tengo bolsillos profundos y infinitos', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1626', 'loot', 'All is mine!', '0', '0', '', 'Tout m’appartient!', 'Alles gehört mir!', '都是我的！', '', '¡Todo es mío!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1627', 'loot', 'Hope no gray shit today', '0', '0', '', 'J’espère qu’il n’y aura pas de merde grise aujourd’hui.', 'Hoffentlich heute kein grauer Mist.', '希望今天没灰装', '', 'Espero que hoy no haya mierda gris', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1628', 'loot', 'This loot is MINE!', '0', '0', '', 'Ce butin est MIEN !', 'Diese Beute gehört MIR!', '这战利品是我的！', '', '¡Este botín es MÍO!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1629', 'loot', 'Looting is disgusting but I need money', '0', '0', '', 'Le pillage est répugnant mais j’ai besoin d’argent', 'Plündern ist ekelhaft, aber ich brauche Geld.', '捡东西真恶心但我需要钱', '', 'El saqueo es repugnante pero necesito dinero...', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1630', 'loot', 'Gold!', '0', '0', '', 'ARGENT !', 'GOLD!', '金币！', '', '¡Oro!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1631', 'loot', 'OK. Let’s see what they’ve got', '0', '0', '', 'D’accord. Voyons ce qu’ils ont.', 'Okay. Schauen wir mal, was sie haben.', '好，看看他们掉了啥', '', 'OK. Veamos qué tienen', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1632', 'loot', 'Do not worry. I will loot eveything', '0', '0', '', 'Ne t’inquiète pas. je vais tout piller', 'Keine Sorge. Ich werde alles looten.', '别担心，我全捡', '', 'No te preocupes. Saquearé todo', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1633', 'loot', 'I am loot ninja', '0', '0', '', 'Je suis un ninja du butin', 'Ich bin ein Loot-Ninja.', '我是拾取忍者', '', 'Soy un ladron de tesoros', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1634', 'loot', 'Do I neeed to roll?', '0', '0', '', 'Est-ce que je dois lancer les dés?', 'Muss ich würfeln?', '需要ROLL点吗？', '', '¿Necesito lanzar dados?', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1635', 'loot', 'Somebody explain me, where they did put all this stuff?', '0', '0', '', 'Quelqu’un m’explique, où ils ont mis tout ça?', 'Kann mir jemand erklären, wo sie das ganze Zeug hingetan haben?', '谁能告诉我，他们把这堆东西放哪的？', '', 'Alguien me explica, ¿dónde pusieron todas estas cosas?', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1636', 'loot', 'No, I won’t loot gray shit', '0', '0', '', 'No way, je ne vais pas voler de la merde grise.', 'Nein, ich loote keinen grauen Mist.', '不，我不捡灰装', '', 'No, no saquearé mierda gris', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1637', 'loot', 'I’m first. I’m first. I’m first.', '0', '0', '', 'Je suis le premier. Je suis le premier. Je suis le premier.', 'Ich bin zuerst! Ich bin zuerst! Ich bin zuerst!', '我先来的。我先。我先。', '', '¡Es mio! ¡Es mio! ¡Es mio!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1638', 'loot', 'Give me your money!', '0', '0', '', 'Désolé, je ne peux pas faire ça.', 'Gib mir dein Geld!', '交出你的钱！', '', '¡Dame todo tu dinero!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1639', 'loot', 'My pockets are empty, I need to fill them', '0', '0', '', 'Mes poches sont vides, il faut que je les remplisse.', 'Meine Taschen sind leer, ich muss sie füllen.', '我口袋空空，得装满', '', 'Mis bolsillos están vacíos y necesitan llenarse!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1640', 'loot', 'I’ve got a new bag for this', '0', '0', '', 'J’ai un nouveau sac pour cela.', 'Ich habe eine neue Tasche dafür.', '我带了新包包', '', 'Tengo una nueva bolsa para esto', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1641', 'loot', 'I hope I won’t aggro anybody while looting', '0', '0', '', 'J’espère ne pas aggro, je vais loot !', 'Ich hoffe, ich ziehe keine Aggro, während ich loote.', '希望捡东西时别ADD', '', 'Espero no ofender a nadie mientras saqueo', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1642', 'loot', 'Please don’t watch. I am looting', '0', '0', '', 'S’il vous plaît, ne regardez pas. je loot', 'Bitte nicht hinschauen. Ich plündere.', '别看，我在捡东西', '', 'Por favor, no mires. Estoy saqueando', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1643', 'loot', 'Ha! You won’t get any piece of it!', '0', '0', '', 'Ha! Tu ne verras rien de cela !', 'Ha! Davon bekommst du nichts ab!', '哈！你毛都别想拿到！', '', '¡Ja! ¡No obtendrás nada de eso!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1644', 'loot', 'Looting is cool', '0', '0', '', 'Le pillage c’est cool', 'Looten ist cool.', '捡东西真爽', '', 'Saquear es genial', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1645', 'loot', 'I like new gear', '0', '0', '', 'J’aime les nouveaux équipements.', 'Ich liebe neue Ausrüstung.', '我喜欢新装备', '', 'Me gusta el equipo nuevo', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1646', 'loot', 'I’l quit if there is nothing valuable again', '0', '0', '', 'j’arrêterai s’il n’y a plus rien de précieux', 'Ich höre auf, wenn es wieder nichts Wertvolles gibt.', '再没好东西我就退', '', 'Me doy por vencido si no hay nada util', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1647', 'loot', 'I hope it is be a pretty ring', '0', '0', '', 'j’espère que c’est une jolie bague', 'Ich hoffe, es ist ein hübscher Ring.', '希望是枚漂亮戒指', '', 'Espero que sea un anillo bonito', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1648', 'loot', 'I’l rip the loot from you', '0', '0', '', 'Je t’arracherai le butin', 'Ich werde dir die Beute entreißen.', '我会从你手里抢战利品', '', 'Te arrancaré el botín', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1649', 'loot', 'Everybody stay off. I’m going to loot', '0', '0', '', 'Tout le monde, restez loin. Je vais piller.', 'Alle zurückbleiben. Ich loote jetzt.', '都别动。我要捡了', '', '¡Alejaos todos! Voy a lootear', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1650', 'loot', 'Sweet loot', '0', '0', '', 'Je me suis procuré un butin incroyable !', 'Tolle Beute!', '好战利品', '', 'Dulce botín', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1651', 'loot', 'The Roll God! Give me an epic today', '0', '0', '', 'Le Dieu des Lancés! Fais-moi vivre une épopée aujourd’hui', 'Oh Würfelgott! Gib mir heute ein Epic!', 'ROLL神！今天给我件紫装', '', '¡El Dios de los dados! Dame un epico hoy', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1652', 'loot', 'Please give me new toys', '0', '0', '', 'S’il te plaît, donne-moi de nouveaux jouets', 'Bitte gib mir neue Spielsachen.', '请给我新玩具', '', 'Por favor, dame nuevos juguetes', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1653', 'loot', 'I hope they carry tasties', '0', '0', '', 'J’espère qu’ils auront des délices.', 'Ich hoffe, sie haben etwas Leckeres dabei.', '希望他们带了美食', '', 'Espero que caiga algo sabrosos', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1654', 'loot', 'The gold is mine. I’ll leave everyting, I promise', '0', '0', '', 'L’or m’appartient. Je laisserai tout, je te le promets.', 'Das Gold gehört mir. Ich lasse den Rest liegen, versprochen.', '金币归我。其他都留，我保证', '', 'El oro es mío. Dejaré todo lo demas, lo prometo!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1655', 'loot', 'No, I can’t resist', '0', '0', '', 'Non, je ne peux pas résister.', 'Nein, ich kann nicht widerstehen.', '不，我忍不住了', '', 'No, no puedo resistir', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1656', 'loot', 'I want more!', '0', '0', '', 'Oh, vous en voulez plus!', 'Ich will mehr!', '我还要！', '', '¡Quiero más!', '', '');
INSERT INTO `ai_playerbot_texts` VALUES ('1657', 'wait_travel_close', 'I am close, wait for me!', '0', '0', '', 'Je suis presque là, attends-moi !', 'Ich bin fast da, wartet auf mich!', '我快到了，等等！', '', '¡Estoy cerca, espérame!', '', 'Я тут рядом, подожди!');
INSERT INTO `ai_playerbot_texts` VALUES ('1658', 'wait_travel_close', 'I’m not far, please wait!', '0', '0', '', 'Je ne suis pas loin, s’il vous plaît patientez !', 'Ich bin nicht weit, bitte wartet!', '我不远，等等！', '', 'No estoy lejos, ¡esperame por favor!', '', 'Я недалеко, погодите!');
INSERT INTO `ai_playerbot_texts` VALUES ('1659', 'wait_travel_medium', 'I’m heading to your location', '0', '0', '', 'Je me dirige vers votre emplacement.', 'Ich bin auf dem Weg zu euch.', '我正赶过去', '', 'Me dirijo a tu ubicación', '', 'Двигаюсь к тебе');
INSERT INTO `ai_playerbot_texts` VALUES ('1660', 'wait_travel_medium', 'I’m coming to you', '0', '0', '', 'Je viens vers vous.', 'Ich komme zu euch.', '我来找你了', '', 'Voy hacia ti', '', 'Иду к тебе');
INSERT INTO `ai_playerbot_texts` VALUES ('1661', 'wait_travel_far', 'I’m traveling to your location', '0', '0', '', 'Je voyage vers votre destination.', 'Ich reise zu eurem Standort.', '正在前往你的位置', '', 'Voy a viajar a tu ubicación', '', 'Направляюсь к тебе');
INSERT INTO `ai_playerbot_texts` VALUES ('1662', 'wait_travel_far', 'I’m trying to get to you', '0', '0', '', 'Je suis en train de l’atteindre', 'Ich versuche, zu euch zu kommen.', '我正想办法过去', '', 'Estoy tratando de llegar a ti', '', 'Пытаюсь до тебя добраться');
