INSERT INTO `ai_playerbot_texts` VALUES ('1674', 'fleeing_far', 'I won’t flee with you, you are too far away', '0', '0', '', 'Je ne vais pas partir avec toi, tu es trop loin.', 'Ich werde nicht mit dir fliehen, du bist zu weit weg.', '不跟你跑，你太远了', '', 'No huiré contigo, estás demasiado lejos', '', 'Я с тобой не побегу, ты слишком далеко');
