INSERT INTO `ai_playerbot_texts` VALUES ('1677', 'error_far', 'It is too far away', '0', '0', '', 'C’est trop loin.', 'Das ist zu weit entfernt.', '太远了', '', 'Estas demasiado lejos', '', 'Слишком далеко');
