INSERT INTO `ai_playerbot_texts` VALUES ('1683', 'error_gbank_rights', 'I have no rights to put items in the first guild bank tab', '0', '0', '', 'Je n’ai pas le droit de mettre des objets dans le premier onglet de la banque de guilde.', 'Ich habe keine Rechte, Gegenstände in den ersten Reiter der Gildenbank zu legen.', '无权在公会银行第一页存东西', '', 'No tengo derechos para depositar objetos en la primera pestaña del banco de hermandad', '', 'Нет прав чтобы класть вещи в первую вкладку гильд банка');
INSERT INTO `ai_playerbot_texts` VALUES ('1684', 'gbank_put', ' put to guild bank', '0', '0', '', ' déposé dans la banque de guilde.', 'in die Gildenbank gelegt.', '存到公会银行', '', ' depositado en el banco de hermandad', '', ' теперь в гильд банке');
