INSERT INTO `ai_playerbot_texts` VALUES ('1698', 'cast_spell_command_summon_error_members', 'I don’t have enough party members around to cast a summon', '0', '0', '', 'Je n’ai pas assez de membres de groupe autour de moi pour lancer une invocation.', 'Ich habe nicht genug Gruppenmitglieder in der Nähe, um eine Beschwörung zu durchzuführen.', '附近队友不足，无法召唤', '', 'No tengo suficientes miembros de grupo alrededor para invocar', '', '');
